import express from 'express';
import { parseUuid } from './http.js';

/**
 * Creates the /api/ai router with two endpoints:
 *
 *  POST /api/ai/simulate
 *    Body: { case_id, center_id, test_ids[] }
 *    Returns deterministic simulation result.
 *
 *  GET  /api/ai/catalogue
 *    Returns the full TEST_CATALOGUE (for frontend dropdowns).
 *
 * Preserves all existing routes registered in server.js (business, billing,
 * imaging, outsource, analytics, auth, appointments).
 *
 * @param {{ requireAuthority: function }} options
 */
export function createAiRouter({ requireAuthority }) {
  const router = express.Router();

  // GET /api/ai/catalogue – returns the test catalogue (no DB needed)
  router.get('/catalogue', requireAuthority, (_req, res) => {
    return res.json({
      success: true,
      data: TEST_CATALOGUE.map(({ test_id, name, unit, normalRange }) => ({
        test_id, name, unit, normalRange
      }))
    });
  });

  // GET /api/ai/config – diagnostic check for environment variables wiring
  router.get('/config', requireAuthority, (_req, res) => {
    return res.json({
      success: true,
      data: {
        supabaseConfigured: Boolean(SUPABASE_URL && SUPABASE_SERVICE_ROLE_KEY),
        geminiConfigured: Boolean(GEMINI_API_KEY),
        apiBaseUrl: VITE_API_BASE_URL
      }
    });
  });

  // POST /api/ai/simulate – run deterministic simulation
  router.post('/simulate', requireAuthority, (req, res) => {
    const { case_id, center_id, test_ids } = req.body || {};

    const caseId = parseUuid(case_id);
    const centerId = parseUuid(center_id);

    if (!caseId) {
      return res.status(400).json({ success: false, error: 'case_id must be a valid UUID.' });
    }
    if (!centerId) {
      return res.status(400).json({ success: false, error: 'center_id must be a valid UUID.' });
    }
    if (!Array.isArray(test_ids) || test_ids.length === 0 || test_ids.some(id => typeof id !== 'string')) {
      return res.status(400).json({ success: false, error: 'test_ids must be a non-empty array of strings.' });
    }

    try {
      const simResult = simulateCase(caseId, centerId, test_ids);

      // Build persistence payload (caller stores if DB is configured)
      const runId = generateRunId(caseId, centerId);
      const persistence = buildPersistencePayload(simResult, runId);

      return res.json({
        success: true,
        data: simResult,
        _persistence_payload: persistence  // Included for DB-connected clients
      });
    } catch (err) {
      return res.status(500).json({ success: false, error: err.message || 'Simulation failed.' });
    }
  });

  return router;
}

/**
 * Stable run ID derived from case_id + center_id + UTC date.
 * Ensures the same simulation for the same case on the same day returns the same audit ID.
 */
function generateRunId(caseId, centerId) {
  const dateStr = new Date().toISOString().slice(0, 10);
  const seed = hashString(`${caseId}::${centerId}::${dateStr}`);
  // Format as pseudo-UUID v4 using the seed
  const hex = seed.toString(16).padStart(8, '0');
  return `${hex.slice(0,8)}-a1b2-4c3d-e5f6-${Date.now().toString(16).slice(-12)}`;
}

import express from 'express';
import { readAnalyticsFilters, sendDatabaseUnavailable } from './http.js';

const filtersSql = `lab_id = $1
  AND ($2::date IS NULL OR ordered_at::date >= $2)
  AND ($3::date IS NULL OR ordered_at::date <= $3)
  AND ($4::uuid IS NULL OR case_id = $4)`;

export function createAnalyticsRouter({ pool, requireAuthority }) {
  const router = express.Router();

  const withFilters = (handler) => async (req, res) => {
    if (!pool) return sendDatabaseUnavailable(res);
    const parsed = readAnalyticsFilters(req.query);
    if (parsed.error) return res.status(400).json({ success: false, error: parsed.error });
    return handler(req, res, parsed.value);
  };

  router.get('/tat', requireAuthority, withFilters(async (req, res, filters) => {
    try {
      const { rows: [row] } = await pool.query(
        `WITH completed AS (
           SELECT extract(epoch FROM (completed_at - ordered_at))::numeric AS duration_seconds
           FROM v_labsetu_test_results
           WHERE ${filtersSql} AND status = 'completed' AND completed_at IS NOT NULL AND completed_at >= ordered_at
         )
         SELECT count(*)::integer AS sample_count,
                COALESCE(round(avg(duration_seconds), 2), 0)::text AS average_seconds,
                COALESCE(round(percentile_cont(0.5) WITHIN GROUP (ORDER BY duration_seconds)::numeric, 2), 0)::text AS median_seconds
         FROM completed`,
        [req.authority.labId, filters.from, filters.to, filters.caseId]
      );
      return res.json({ success: true, data: {
        sampleCount: Number(row.sample_count),
        averageSeconds: row.average_seconds,
        medianSeconds: row.median_seconds
      } });
    } catch {
      return res.status(500).json({ success: false, error: 'Unable to calculate turnaround time.' });
    }
  }));

  router.get('/abnormal-results', requireAuthority, withFilters(async (req, res, filters) => {
    try {
      const { rows: [row] } = await pool.query(
        `SELECT count(*)::integer AS evaluated_count,
                count(*) FILTER (WHERE is_abnormal)::integer AS abnormal_count,
                CASE WHEN count(*) = 0 THEN 0
                     ELSE round(100.0 * count(*) FILTER (WHERE is_abnormal) / count(*), 2)
                END::text AS abnormal_rate_percent
         FROM v_labsetu_test_results
         WHERE ${filtersSql} AND status = 'completed' AND completed_at IS NOT NULL AND is_abnormal IS NOT NULL`,
        [req.authority.labId, filters.from, filters.to, filters.caseId]
      );
      return res.json({ success: true, data: {
        evaluatedCount: Number(row.evaluated_count),
        abnormalCount: Number(row.abnormal_count),
        abnormalRatePercent: row.abnormal_rate_percent
      } });
    } catch {
      return res.status(500).json({ success: false, error: 'Unable to calculate abnormal result rate.' });
    }
  }));

  router.get('/test-frequency', requireAuthority, withFilters(async (req, res, filters) => {
    try {
      const result = await pool.query(
        `SELECT test_id AS "testId", test_name AS "testName", count(*)::integer AS frequency
         FROM v_labsetu_test_results
         WHERE ${filtersSql} AND status <> 'cancelled'
         GROUP BY test_id, test_name
         ORDER BY frequency DESC, test_name, test_id`,
        [req.authority.labId, filters.from, filters.to, filters.caseId]
      );
      return res.json({ success: true, data: result.rows });
    } catch {
      return res.status(500).json({ success: false, error: 'Unable to calculate test frequency.' });
    }
  }));

  return router;
}

import jwt from 'jsonwebtoken';

export function createAuthorityMiddleware(jwtSecret, authContractVerified = false) {
  return (req, res, next) => {
    if (!jwtSecret) {
      return res.status(503).json({ success: false, error: 'Authentication is not configured.' });
    }
    if (authContractVerified !== true) {
      return res.status(503).json({ success: false, error: 'The JWT claim contract has not been verified.' });
    }

    const authorization = req.get('authorization') || '';
    const token = authorization.startsWith('Bearer ') ? authorization.slice(7) : '';
    if (!token) return res.status(401).json({ success: false, error: 'A bearer token is required.' });

    try {
      const claims = jwt.verify(token, jwtSecret, { algorithms: ['HS256'], audience: 'authenticated' });
      if (!Number.isFinite(claims.exp)) {
        return res.status(401).json({ success: false, error: 'The bearer token must have an expiry.' });
      }
      const role = claims.app_metadata?.role ?? claims.role;
      const labId = claims.app_metadata?.lab_id ?? claims.lab_id ?? claims.labId;

      if (role !== 'authority') {
        return res.status(403).json({ success: false, error: 'Authority access is required.' });
      }
      if (typeof labId !== 'string' || !labId.trim()) {
        return res.status(403).json({ success: false, error: 'The token has no laboratory scope.' });
      }

      req.authority = { labId: labId.trim() };
      return next();
    } catch {
      return res.status(401).json({ success: false, error: 'The bearer token is invalid or expired.' });
    }
  };
}

import express from 'express';
import { parseIsoDate, parseUuid, sendDatabaseUnavailable } from './http.js';

export function createBusinessRouter({ pool, requireAuthority }) {
  const router = express.Router();

  router.get(['/due-reports', '/dues'], requireAuthority, async (req, res) => {
    if (!pool) return sendDatabaseUnavailable(res);

    const { caseType = null, patientId: rawPatientId, from: rawFrom, to: rawTo, asOf: rawAsOf } = req.query;
    const patientId = rawPatientId === undefined ? null : parseUuid(rawPatientId);
    const from = rawFrom === undefined ? null : parseIsoDate(rawFrom);
    const to = rawTo === undefined ? null : parseIsoDate(rawTo);
    const asOf = rawAsOf === undefined ? new Date().toISOString().slice(0, 10) : parseIsoDate(rawAsOf);

    if ((caseType !== null && (typeof caseType !== 'string' || caseType.length > 64)) ||
        (rawPatientId !== undefined && !patientId) ||
        (rawFrom !== undefined && !from) || (rawTo !== undefined && !to) || !asOf) {
      return res.status(400).json({ success: false, error: 'Invalid caseType, patientId, from, to, or asOf filter.' });
    }
    if (from && to && from > to) {
      return res.status(400).json({ success: false, error: 'from must be on or before to.' });
    }

    const sql = `
      WITH filtered AS (
        SELECT case_id, patient_id, patient_name, case_type, case_created_at::date AS case_date,
               billed_amount, paid_amount, due_at::date AS due_date,
               GREATEST(billed_amount - paid_amount, 0)::numeric AS outstanding_amount,
               GREATEST($4::date - due_at::date, 0)::integer AS age_days
        FROM v_labsetu_case_balances
        WHERE lab_id = $1
          AND ($2::text IS NULL OR case_type = $2)
          AND ($3::uuid IS NULL OR patient_id = $3)
          AND ($5::date IS NULL OR case_created_at::date >= $5)
          AND ($6::date IS NULL OR case_created_at::date <= $6)
      ), due AS (
        SELECT * FROM filtered WHERE outstanding_amount > 0
      )
      SELECT
        COALESCE(jsonb_agg(jsonb_build_object(
          'caseId', case_id,
          'patientId', patient_id,
          'patientName', patient_name,
          'caseType', case_type,
          'caseDate', case_date,
          'dueDate', due_date,
          'billedAmount', billed_amount::text,
          'paidAmount', paid_amount::text,
          'outstandingAmount', outstanding_amount::text,
          'ageDays', age_days
        ) ORDER BY age_days DESC, case_date, case_id), '[]'::jsonb) AS cases,
        count(*)::integer AS case_count,
        COALESCE(round(sum(billed_amount), 2), 0)::text AS billed_total,
        COALESCE(round(sum(paid_amount), 2), 0)::text AS paid_total,
        COALESCE(round(sum(outstanding_amount), 2), 0)::text AS outstanding_total,
        COALESCE(round(sum(outstanding_amount) FILTER (WHERE age_days <= 7), 2), 0)::text AS days_0_7,
        COALESCE(round(sum(outstanding_amount) FILTER (WHERE age_days BETWEEN 8 AND 30), 2), 0)::text AS days_8_30,
        COALESCE(round(sum(outstanding_amount) FILTER (WHERE age_days BETWEEN 31 AND 59), 2), 0)::text AS days_31_59,
        COALESCE(round(sum(outstanding_amount) FILTER (WHERE age_days >= 60), 2), 0)::text AS days_60_plus
      FROM due`;

    try {
      const { rows: [row] } = await pool.query(sql, [req.authority.labId, caseType || null, patientId, asOf, from, to]);
      return res.json({
        success: true,
        data: {
          asOf,
          caseCount: Number(row.case_count),
          billedTotal: row.billed_total,
          paidTotal: row.paid_total,
          outstandingTotal: row.outstanding_total,
          aging: {
            days0To7: row.days_0_7,
            days8To30: row.days_8_30,
            days31To59: row.days_31_59,
            days60Plus: row.days_60_plus
          },
          cases: row.cases
        }
      });
    } catch {
      return res.status(500).json({ success: false, error: 'Unable to load due reports.' });
    }
  });

  return router;
}

export function sendDatabaseUnavailable(res) {
  return res.status(503).json({
    success: false,
    error: 'Database integration is not configured.'
  });
}

export function parseIsoDate(value) {
  if (typeof value !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(value) || value.startsWith('0000-')) return null;
  const parsed = new Date(`${value}T00:00:00.000Z`);
  return Number.isNaN(parsed.valueOf()) || parsed.toISOString().slice(0, 10) !== value ? null : value;
}

export function parseUuid(value) {
  if (typeof value !== 'string') return null;
  return /^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(value)
    ? value
    : null;
}

export function readAnalyticsFilters(query) {
  const from = query.from === undefined ? null : parseIsoDate(query.from);
  const to = query.to === undefined ? null : parseIsoDate(query.to);
  const caseId = query.caseId === undefined ? null : parseUuid(query.caseId);

  if ((query.from !== undefined && !from) || (query.to !== undefined && !to) || (query.caseId !== undefined && !caseId)) {
    return { error: 'Use ISO dates (YYYY-MM-DD) and a valid caseId.' };
  }
  if (from && to && from > to) return { error: 'from must be on or before to.' };

  return { value: { from, to, caseId } };
}

import express from 'express';
import { parseUuid, sendDatabaseUnavailable } from './http.js';

const imagingTypes = new Set(['ct_scan', 'usg', 'digital_xray']);
const imagingStatuses = new Set(['requested', 'scheduled', 'in_progress', 'completed', 'cancelled']);
const imagingColumns = {
  status: 'status',
  accessionNumber: 'accession_number',
  referredBy: 'referred_by',
  notes: 'notes'
};
const imagingSelect = `id, patient_id AS "patientId", case_type AS "caseType", status,
  accession_number AS "accessionNumber", referred_by AS "referredBy", notes,
  created_at AS "createdAt", updated_at AS "updatedAt"`;

function validOptionalText(value, maxLength) {
  return value === null || value === undefined || (typeof value === 'string' && value.length <= maxLength);
}

export function createImagingRouter({ pool, requireAuthority }) {
  const router = express.Router();

  router.get('/cases', requireAuthority, async (req, res) => {
    if (!pool) return sendDatabaseUnavailable(res);
    const { caseType = null, status = null } = req.query;
    if ((caseType !== null && !imagingTypes.has(caseType)) || (status !== null && !imagingStatuses.has(status))) {
      return res.status(400).json({ success: false, error: 'Invalid caseType or status filter.' });
    }
    try {
      const result = await pool.query(
        `SELECT ${imagingSelect} FROM imaging_cases
         WHERE lab_id = $1 AND ($2::text IS NULL OR case_type = $2) AND ($3::text IS NULL OR status = $3)
         ORDER BY created_at DESC, id`,
        [req.authority.labId, caseType, status]
      );
      return res.json({ success: true, data: result.rows });
    } catch {
      return res.status(500).json({ success: false, error: 'Unable to load imaging cases.' });
    }
  });

  router.get('/cases/:id', requireAuthority, async (req, res) => {
    if (!pool) return sendDatabaseUnavailable(res);
    const id = parseUuid(req.params.id);
    if (!id) return res.status(400).json({ success: false, error: 'A valid case id is required.' });
    try {
      const { rows: [row] } = await pool.query(
        `SELECT ${imagingSelect} FROM imaging_cases WHERE id = $1 AND lab_id = $2`,
        [id, req.authority.labId]
      );
      return row ? res.json({ success: true, data: row }) : res.status(404).json({ success: false, error: 'Imaging case not found.' });
    } catch {
      return res.status(500).json({ success: false, error: 'Unable to load imaging case.' });
    }
  });

  router.post('/cases', requireAuthority, async (req, res) => {
    if (!pool) return sendDatabaseUnavailable(res);
    const { patientId, caseType, accessionNumber = null, referredBy = null, notes = null } = req.body || {};
    const patientUuid = parseUuid(patientId);
    if (!patientUuid || !imagingTypes.has(caseType) ||
        !validOptionalText(accessionNumber, 128) || !validOptionalText(referredBy, 256) || !validOptionalText(notes, 4000)) {
      return res.status(400).json({ success: false, error: 'Provide a valid patientId, caseType, and optional text fields.' });
    }
    try {
      const { rows: [row] } = await pool.query(
        `INSERT INTO imaging_cases (lab_id, patient_id, case_type, status, accession_number, referred_by, notes)
         VALUES ($1, $2, $3, 'requested', $4, $5, $6) RETURNING ${imagingSelect}`,
        [req.authority.labId, patientUuid, caseType, accessionNumber, referredBy, notes]
      );
      return res.status(201).json({ success: true, data: row });
    } catch {
      return res.status(500).json({ success: false, error: 'Unable to create imaging case.' });
    }
  });

  router.put('/cases/:id', requireAuthority, async (req, res) => {
    if (!pool) return sendDatabaseUnavailable(res);
    const id = parseUuid(req.params.id);
    const body = req.body || {};
    const entries = Object.entries(imagingColumns).filter(([key]) => Object.hasOwn(body, key));
    if (!id || entries.length === 0 || entries.some(([key]) =>
      (key === 'status' ? !imagingStatuses.has(body[key]) : !validOptionalText(body[key], key === 'notes' ? 4000 : key === 'referredBy' ? 256 : 128)))) {
      return res.status(400).json({ success: false, error: 'Provide a valid case id and at least one allowed update field.' });
    }
    const values = [id, req.authority.labId];
    const assignments = entries.map(([key]) => {
      values.push(body[key]);
      return `${imagingColumns[key]} = $${values.length}`;
    });
    try {
      const { rows: [row] } = await pool.query(
        `UPDATE imaging_cases SET ${assignments.join(', ')}, updated_at = now()
         WHERE id = $1 AND lab_id = $2 RETURNING ${imagingSelect}`,
        values
      );
      return row ? res.json({ success: true, data: row }) : res.status(404).json({ success: false, error: 'Imaging case not found.' });
    } catch {
      return res.status(500).json({ success: false, error: 'Unable to update imaging case.' });
    }
  });

  return router;
}

