                  </label>
                  <input
                    type="text"
                    id="security-answer-input"
                    placeholder="Enter the answer you configured during registration"
                    value={securityAnswerInput}
                    onChange={(e) => setSecurityAnswerInput(e.target.value)}
                    required
                    style={{ marginTop: '0.35rem' }}
                  />
                </div>

                {/* Field 2: New Password */}
                <div className="registration-input-group" style={{ marginBottom: '1.25rem' }}>
                  <label htmlFor="new-password">New Password (min 6 chars) <span className="req">*</span></label>
                  <div className="password-input-wrapper">
                    <input
                      type={showNewPassword ? 'text' : 'password'}
                      id="new-password"
                      placeholder="Enter new password"
                      value={newPassword}
                      onChange={(e) => setNewPassword(e.target.value)}
                      required
                    />
                    <button type="button" className="password-toggle-btn" onClick={() => setShowNewPassword(!showNewPassword)} tabIndex={-1} aria-label={showNewPassword ? 'Hide password' : 'Show password'}>
                      {showNewPassword ? <EyeSlashIcon className="pw-toggle-icon" /> : <EyeIcon className="pw-toggle-icon" />}
                    </button>
                  </div>
                  {newPassword && (
                    <div style={{ marginTop: '0.35rem', fontSize: '0.75rem', color: '#64748b' }}>
                      Strength: <strong style={{ color: getPasswordStrength(newPassword).color }}>{getPasswordStrength(newPassword).label}</strong>
                    </div>
                  )}
                </div>

                {/* Submit button: Update Password */}
                <button type="submit" className="registration-button primary" disabled={isSubmitting}>
                  {isSubmitting ? 'Updating Password...' : 'Update Password'}
                </button>

                <button
                  type="button"
                  className="registration-button secondary back-button"
                  onClick={() => setForgotStep(1)}
                  disabled={isSubmitting}
                >
                  <ArrowLeftIcon style={{ width: '16px' }} />
                  Change Email
                </button>
              </form>
            )}

            {/* Step 3 (Success): Confirmation state with auto-redirect to login */}
            {forgotStep === 3 && (
              <div className="forgot-success-state">
                <CheckCircleIcon className="success-big-icon" />
                <h3 className="success-heading">Password Reset Successful</h3>
                <p className="success-sub">
                  Your password has been securely updated in the database. You can now log into your account with your new credentials.
                </p>
                <button
                  type="button"
                  className="registration-button primary"
                  onClick={() => {
                    setLoginEmail(forgotEmail);
                    setLoginPassword('');
                    switchMode('signin');
                  }}
                >
                  Proceed to Sign In
                </button>
              </div>
            )}
          </div>
        )}

        </div>
      </div>

      <Footer />
    </div>
  );
}

/**
 * LabSetu AI Simulation Service
 *
 * Frontend mirror of the backend AI Simulation Engine.
 * Provides fully-offline deterministic simulation so the app works
 * during demos without a live backend, while also calling the real
 * /api/ai/simulate endpoint when available.
 *
 * State is persisted to localStorage under the key `labsetu_sim_state`
 * so results survive browser refreshes (same seeding guarantees on FE).
 */

import apiClient from './apiClient.js';

// ─── Deterministic PRNG (mirrors backend aiSimulationEngine.js) ──────────────

function hashString(str) {
  let h = 0x12345678;
  for (let i = 0; i < str.length; i++) {
    h = (Math.imul(h, 31) + str.charCodeAt(i)) >>> 0;
  }
  return h;
}

function mulberry32(seed) {
  let s = seed >>> 0;
  return function () {
    s += 0x6d2b79f5;
    let z = s;
    z = Math.imul(z ^ (z >>> 15), z | 1);
    z ^= z + Math.imul(z ^ (z >>> 7), z | 61);
    return ((z ^ (z >>> 14)) >>> 0) / 4294967296;
  };
}

function seededRng(caseId, testId) {
  return mulberry32(hashString(`${caseId}::${testId}`));
}

// ─── Flag / Status helpers ────────────────────────────────────────────────────

const FLAG = { N: 'N', L: 'L', H: 'H', CL: 'C-L', CH: 'C-H', NA: 'NA' };
const STATUS = { NORMAL: 'NORMAL', ABNORMAL: 'ABNORMAL', CRITICAL: 'CRITICAL', UNAVAILABLE: 'UNAVAILABLE' };

export function computeFlag(value, ref) {
  if (ref.min == null || ref.max == null) return { flag: FLAG.NA, status: STATUS.UNAVAILABLE };
  const critLow  = ref.criticalLow  ?? ref.min * 0.6;
  const critHigh = ref.criticalHigh ?? ref.max * 1.5;
  if (value <= critLow)  return { flag: FLAG.CL, status: STATUS.CRITICAL };
  if (value >= critHigh) return { flag: FLAG.CH, status: STATUS.CRITICAL };
  if (value < ref.min)   return { flag: FLAG.L,  status: STATUS.ABNORMAL };
  if (value > ref.max)   return { flag: FLAG.H,  status: STATUS.ABNORMAL };
  return { flag: FLAG.N, status: STATUS.NORMAL };
}

