const TEST_MAP = Object.fromEntries(TEST_CATALOGUE.map(t => [t.test_id, t]));

// ─── Core offline simulation (mirrors server logic) ──────────────────────────

function simulateOffline(caseId, centerId, testIds) {
  const validationNotes = [];
  const results = [];

  for (const testId of testIds) {
    const def = TEST_MAP[testId];
    if (!def) { validationNotes.push(`test_id "${testId}" not in catalogue – skipped.`); continue; }

    const ref = def.normalRange;
    const hasRange = ref && ref.min != null && ref.max != null;

    if (!hasRange) {
      results.push({ test_id: testId, value: 0, unit: def.unit, reference_range: { min: null, max: null, text: 'N/A' }, flag: FLAG.NA, status: STATUS.UNAVAILABLE });
      continue;
    }

    const rng = seededRng(caseId, testId);
    const r = rng();
    const bucket = rng();

    let value;
    if (bucket < 0.70) {
      value = ref.min + r * (ref.max - ref.min);
    } else if (bucket < 0.90) {
      const swing = rng() < 0.5;
      const margin = (ref.max - ref.min) * 0.3;
      value = swing ? ref.min - (rng() * margin) : ref.max + (rng() * margin);
    } else {
      const swing = rng() < 0.5;
      value = swing ? (def.criticalLow ?? ref.min * 0.5) : (def.criticalHigh ?? ref.max * 1.6);
    }

    value = Math.max(def.hardMin, Math.min(def.hardMax, value));
    value = Math.round(value * 100) / 100;

    const { flag, status } = computeFlag(value, { min: ref.min, max: ref.max, criticalLow: def.criticalLow, criticalHigh: def.criticalHigh });
    results.push({ test_id: testId, value, unit: def.unit, reference_range: { min: ref.min, max: ref.max, text: `${ref.min} – ${ref.max} ${def.unit}` }, flag, status });
  }

  let abnormal_count = 0, critical_count = 0;
  for (const r of results) {
    if (r.status === STATUS.CRITICAL) critical_count++;
    else if (r.status === STATUS.ABNORMAL) abnormal_count++;
  }

  const fc = results.reduce((a, r) => { a[r.flag] = (a[r.flag] || 0) + 1; return a; }, {});
  const parts = [];
  if (fc['N'])   parts.push(`${fc['N']} result(s) within reference range`);
  if (fc['L'])   parts.push(`${fc['L']} result(s) below reference range`);
  if (fc['H'])   parts.push(`${fc['H']} result(s) above reference range`);
  if (fc['C-L']) parts.push(`${fc['C-L']} result(s) critically low (C-L)`);
  if (fc['C-H']) parts.push(`${fc['C-H']} result(s) critically high (C-H)`);

  return {
    schema_version: '1.0',
    case_id: caseId,
    center_id: centerId,
    results,
    summary: { total_tests: results.length, abnormal_count, critical_count },
    impression: parts.join('; ') + '. Synthetic demo data only.',
    validation_notes: validationNotes,
    _source: 'offline-sim'
  };
}

// ─── localStorage State Persistence ──────────────────────────────────────────

const STORAGE_KEY = 'labsetu_sim_state';

function loadState() {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    return raw ? JSON.parse(raw) : {};
  } catch { return {}; }
}

function saveState(state) {
  try { localStorage.setItem(STORAGE_KEY, JSON.stringify(state)); } catch { /* quota errors silenced */ }
}

// ─── Public API ───────────────────────────────────────────────────────────────

/**
 * Run simulation for a case. Tries backend first, falls back to offline.
 * Result is persisted to localStorage under case_id for refresh safety.
 *
 * @param {string} caseId    UUID (case_id column)
 * @param {string} centerId  UUID (center_id column)
 * @param {string[]} testIds Array of test_id strings
 * @param {boolean} [force]  Force re-simulation even if cached
 * @returns {Promise<object>} simulation result
 */
export async function runSimulation(caseId, centerId, testIds, force = false) {
  // 1. Return cached result if available (refresh-safe)
  if (!force) {
    const state = loadState();
    if (state[caseId]) return { ...state[caseId], _source: 'cache' };
  }

  // 2. Try backend
  try {
    const resp = await apiClient.post('/ai/simulate', { case_id: caseId, center_id: centerId, test_ids: testIds });
    if (resp.success && resp.data?.data) {
      const result = { ...resp.data.data, _source: 'backend' };
      const state = loadState();
      state[caseId] = result;
      saveState(state);
      return result;
    }
  } catch { /* fall through to offline */ }

  // 3. Offline deterministic simulation
  const result = simulateOffline(caseId, centerId, testIds);
  const state = loadState();
  state[caseId] = result;
  saveState(state);
  return result;
}

/**
 * Clear a specific case's cached simulation result.
 * @param {string} caseId
 */
export function clearCachedResult(caseId) {
  const state = loadState();
  delete state[caseId];
  saveState(state);
}

/** Clear all cached simulation results. */
export function clearAllCachedResults() {
  localStorage.removeItem(STORAGE_KEY);
}

/**
 * Get all currently cached simulation results.
 * @returns {object} map of case_id → result
 */
export function getAllCachedResults() {
  return loadState();
}

export { STATUS, FLAG };

/**
 * LabSetu Centralized API Client
 *
 * Configured to communicate with any standard REST backend (Node.js, Express,
 * Python FastAPI/Django, Go, Spring Boot, etc.).
 *
 * Features:
 * - Automatic Authorization Bearer token header injection
 * - Configurable Base URL via VITE_API_BASE_URL (.env / .env.production)
 * - Standardized error handling and JSON serialization
 * - Graceful fallback to local mock data if backend server is not running
 *
 * Base URL resolution priority:
 *   1. VITE_API_BASE_URL env var (set in .env / .env.production)
 *   2. https://labsetu-backend.onrender.com  when running in production build
 *      but no env var was embedded (safety net)
 *   3. http://localhost:5000  for local dev
 */

import { logger } from '../utils/logger';

const resolveBaseUrl = () => {
  // 1. Explicit env var — set in .env (dev) or .env.production (Vercel build)
  if (import.meta.env.VITE_API_BASE_URL) {
    const raw = import.meta.env.VITE_API_BASE_URL.replace(/\/+$/, '');
    return raw.endsWith('/api') ? raw : `${raw}/api`;
  }

  // 2. Running in a Vite production build without an explicit env var
  //    → point at the live Render backend so the app works on Vercel
  if (import.meta.env.PROD) {
    return 'https://labsetu-backend.onrender.com/api';
  }

  // 3. Local development fallback
  return 'http://localhost:5000/api';
};

const API_BASE_URL   = resolveBaseUrl();
const FORCE_MOCK     = import.meta.env.VITE_USE_MOCK       === 'true';
const ENABLE_LOGS    = import.meta.env.VITE_ENABLE_API_LOGS === 'true';

class ApiClient {
  constructor() {
    this.baseUrl            = API_BASE_URL;
    this.isBackendAvailable = null; // null: unknown, true: online, false: offline
  }

  /** Returns current JWT token from sessionStorage or localStorage */
  getToken() {
    const path = typeof window !== 'undefined' ? window.location.pathname : '';
    const scopedKey = path.startsWith('/portal')
      ? 'labsetu_patient_token'
      : 'labsetu_authority_token';
    return (
      sessionStorage.getItem(scopedKey)        ||
      localStorage.getItem(scopedKey)          ||
      sessionStorage.getItem('labsetu_token')  ||
      localStorage.getItem('labsetu_token')    ||
      null
    );
  }

  /** Sets the JWT token in both sessionStorage and localStorage */
  setToken(token) {
    if (token) {
      sessionStorage.setItem('labsetu_token', token);
      localStorage.setItem('labsetu_token', token);
    } else {
      sessionStorage.removeItem('labsetu_token');
      localStorage.removeItem('labsetu_token');
    }
  }

  /** Builds full headers including Bearer auth token if present */
  getHeaders(customHeaders = {}) {
    const headers = {
      'Content-Type': 'application/json',
      'Accept':       'application/json',
      ...customHeaders
    };
    const token = this.getToken();
    if (token) headers['Authorization'] = `Bearer ${token}`;
    return headers;
  }

  /**
   * Centralized HTTP request runner with transparent fallback.
   *
   * Fallback logic:
   *  - FORCE_MOCK flag         → always use fallbackFn
   *  - Network error           → use fallbackFn if provided
   *  - 4xx / 5xx HTTP status   → use fallbackFn if provided (prevents console error spam)
   *  - No fallbackFn available → return { success: false, error }
   */
  async request(endpoint, options = {}, fallbackFn = null) {
    if (FORCE_MOCK && fallbackFn) {
      if (ENABLE_LOGS) console.log(`[API Mock] ${options.method || 'GET'} ${endpoint}`);
      return await fallbackFn();
    }

    const url    = endpoint.startsWith('http')
      ? endpoint
      : `${this.baseUrl}${endpoint.startsWith('/') ? '' : '/'}${endpoint}`;
    const method = options.method || 'GET';

    const config = {
      method,
      headers: this.getHeaders(options.headers),
      ...options
    };

    if (config.body && typeof config.body === 'object' && !(config.body instanceof FormData)) {
      config.body = JSON.stringify(config.body);
    }

    if (ENABLE_LOGS) {
      console.log(`[API Request] ${method} ${url}`, options.body || '');
    }

    try {
      const response = await fetch(url, config);

      // Handle 401 Unauthorized globally
      if (response.status === 401) {
        this.setToken(null);
      }

      const contentType = response.headers.get('content-type') || '';
      let data = null;

      if (contentType.includes('application/json')) {
        data = await response.json();
      } else {
        data = await response.text();
      }

      if (ENABLE_LOGS) {
        console.log(`[API Response ${response.status}] ${method} ${url}:`, data);
      }

      if (!response.ok) {
        logger.network(`HTTP ${response.status} ${response.statusText || 'Error'} on ${method} ${url}`, {
          endpoint,
          status: response.status,
          method,
          data
        });

        // For /api/resources/* a non-ok response should still use fallback
        // rather than throwing, so the UI never breaks.
        if (fallbackFn) {
          this.isBackendAvailable = false;
          return await fallbackFn();
        }
        const errorMessage =
          (data && (data.error || data.message)) ||
          `Request failed with status ${response.status}`;
        throw new Error(errorMessage);
      }

      this.isBackendAvailable = true;
      return { success: true, data, status: response.status };

    } catch (err) {
      // Log through diagnostic interceptor
      if (ENABLE_LOGS) {
        logger.network(`[API Fallback] ${method} ${url}`, { error: err.message });
      }

      if (fallbackFn) {
        this.isBackendAvailable = false;
        return await fallbackFn();
      }

      logger.network(`Network API connection error: ${method} ${url}`, {
        error: err.message,
        stack: err.stack
      });

      return {
        success: false,
        error:   err.message || 'Unable to connect to backend server.',
        status:  0
      };
    }
  }

  // ─── Convenience methods ─────────────────────────────────────────────────────
  get(endpoint, options = {}, fallbackFn = null) {
    return this.request(endpoint, { ...options, method: 'GET' }, fallbackFn);
  }

  post(endpoint, body, options = {}, fallbackFn = null) {
    return this.request(endpoint, { ...options, method: 'POST', body }, fallbackFn);
  }

  put(endpoint, body, options = {}, fallbackFn = null) {
    return this.request(endpoint, { ...options, method: 'PUT', body }, fallbackFn);
  }

  patch(endpoint, body, options = {}, fallbackFn = null) {
    return this.request(endpoint, { ...options, method: 'PATCH', body }, fallbackFn);
  }

  delete(endpoint, options = {}, fallbackFn = null) {
    return this.request(endpoint, { ...options, method: 'DELETE' }, fallbackFn);
  }
}

