/**
 * LabSetu Diagnostic Report Service
 * 
 * Endpoints:
 * - GET    /api/reports          -> Get test reports (filter by uhid, labId, date)
 * - GET    /api/reports/:id      -> Get single report with test parameters & values
 * - POST   /api/reports          -> Generate/publish a new diagnostic report
 * - GET    /api/reports/:id/pdf  -> Download PDF report stream / URL
 */

import apiClient from './apiClient';
import { demoCitizenReports } from '../data/mockLabData';

const STORAGE_KEY = 'labsetu-demo:citizen_reports';

const getLocalReports = () => {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    return raw ? JSON.parse(raw) : (demoCitizenReports || []);
  } catch {
    return demoCitizenReports || [];
  }
};

export const reportService = {
  /**
   * Fetch all reports
   */
  async getReports(queryParams = {}) {
    const fallbackFn = async () => {
      let reports = getLocalReports();
      if (queryParams.uhid) {
        reports = reports.filter(r => r.uhid === queryParams.uhid);
      }
      if (queryParams.status) {
        reports = reports.filter(r => r.status?.toLowerCase() === queryParams.status.toLowerCase());
      }
      return { success: true, data: reports };
    };

    const queryString = new URLSearchParams(queryParams).toString();
    const endpoint = `/reports${queryString ? `?${queryString}` : ''}`;
    return await apiClient.get(endpoint, {}, fallbackFn);
  },

  /**
   * Get report by ID
   */
  async getReportById(id) {
    const fallbackFn = async () => {
      const reports = getLocalReports();
      const report = reports.find(r => String(r.id) === String(id));
      if (!report) return { success: false, error: 'Report not found' };
      return { success: true, data: report };
    };

    return await apiClient.get(`/reports/${id}`, {}, fallbackFn);
  },

  /**
   * Create or publish a new report
   */
  async createReport(reportData) {
    const fallbackFn = async () => {
      const reports = getLocalReports();
      const newReport = {
        id: `REP-${Date.now().toString().slice(-6)}`,
        date: new Date().toLocaleDateString('en-GB'),
        status: 'Available',
        ...reportData
      };
      reports.unshift(newReport);
      try {
        localStorage.setItem(STORAGE_KEY, JSON.stringify(reports));
      } catch (err) {
        console.error('Failed to save report', err);
      }
      return { success: true, data: newReport };
    };

    return await apiClient.post('/reports', reportData, {}, fallbackFn);
  },

  /**
   * Get PDF download URL or stream
   */
  async getReportPdfUrl(id) {
    return `${apiClient.baseUrl}/reports/${id}/pdf`;
  }
};

export default reportService;

/**
 * LabSetu Array Safety Utilities
 *
 * Prevents "map / filter is not a function" runtime crashes that occur when
 * API calls return non-array shapes like { success: false } or { error: "…" }.
 *
 * Usage:
 *   import { ensureArray } from '../../utils/arrayUtils';
 *   const safeList = ensureArray(rawApiData);
 *   safeList.map((item) => …);
 */

/**
 * Normalises any value into a guaranteed JavaScript array.
 *
 * Priority:
 *  1. Already an array          → returned as-is
 *  2. Has a `.data` array       → returns `val.data`
 *  3. Has a `.records` array    → returns `val.records`
 *  4. Has a `.results` array    → returns `val.results`
 *  5. Has a `.items` array      → returns `val.items`
 *  6. Anything else (null, obj, undefined) → returns []
 *
 * @param {*} val - Raw value from API / hook state
 * @returns {Array}
 */
export function ensureArray(val) {
  if (Array.isArray(val)) return val;
  if (val && Array.isArray(val.data))    return val.data;
  if (val && Array.isArray(val.records)) return val.records;
  if (val && Array.isArray(val.results)) return val.results;
  if (val && Array.isArray(val.items))   return val.items;
  return [];
}

/**
 * Normalises any value into a guaranteed plain object.
 *
 * @param {*} val - Raw value from API / hook state
 * @param {Object} [defaults={}] - Default object if val is not usable
 * @returns {Object}
 */
export function ensureObject(val, defaults = {}) {
  if (val && typeof val === 'object' && !Array.isArray(val)) return val;
  return defaults;
}

export default ensureArray;

