/* Tooltips */
.newbill-tooltip-wrapper {
  position: relative;
  display: inline-flex;
  align-items: center;
  cursor: help;
  color: #6b7280;
}

.newbill-tooltip-wrapper:hover {
  color: #15803d;
}

.newbill-tooltip {
  position: absolute;
  bottom: 130%;
  left: 50%;
  transform: translateX(-50%);
  background-color: #1f2937;
  color: white;
  padding: 0.75rem;
  border-radius: 6px;
  font-size: 0.8rem;
  font-weight: 400;
