  text-align: center;
  opacity: 0;
  visibility: hidden;
  transition: all 0.2s ease-in-out;
  z-index: 50;
  box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1);
  pointer-events: none;
  line-height: 1.4;
}

.newbill-tooltip::after {
  content: "";
  position: absolute;
  top: 100%;
  left: 50%;
  margin-left: -5px;
  border-width: 5px;
  border-style: solid;
  border-color: #1f2937 transparent transparent transparent;
}

.newbill-tooltip-wrapper:hover .newbill-tooltip {
  opacity: 1;
  visibility: visible;
  bottom: 150%;
}

.newbill-grid-2 {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 1rem;
