              <div style={{ background: '#f8fafc', padding: '1rem', borderRadius: '8px', border: '1px solid #e2e8f0' }}>
                <span style={{ fontSize: '0.8rem', color: '#64748b' }}>Total Bills Executed</span>
                <div style={{ fontSize: '1.35rem', fontWeight: '700', color: '#0f172a', marginTop: '0.25rem' }}>264 Bills</div>
              </div>
            </div>
            <div style={{ display: 'flex', justifyContent: 'flex-end' }}>
              <button type="button" onClick={() => setIsMonthlyModalOpen(false)} style={{ padding: '0.55rem 1rem', borderRadius: '6px', border: 'none', background: '#15803d', color: '#ffffff', fontWeight: '600', cursor: 'pointer' }}>Close Overview</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

import React, { useState } from 'react';
import { ArrowDownTrayIcon, CheckCircleIcon, DocumentArrowDownIcon } from '@heroicons/react/24/outline';
import './BusinessShared.css';

export default function DataExport() {
  const [dataset, setDataset] = useState('bills');
  const [format, setFormat] = useState('csv');
  const [fromDate, setFromDate] = useState('2026-09-01');
  const [toDate, setToDate] = useState('2026-09-13');
  const [isExporting, setIsExporting] = useState(false);
  const [downloadSuccess, setDownloadSuccess] = useState(false);

  const handleExport = (e) => {
    e.preventDefault();
    setIsExporting(true);

    setTimeout(() => {
      let content = '';
      let filename = `labsetu_${dataset}_export_${fromDate}_to_${toDate}`;

      if (dataset === 'bills') {
        if (format === 'csv') {
          content = 'Bill ID,Patient Name,Date,Amount,Payment Method,Status\nINV-2026-1049,Riya Sharma,12/09/2026,850,UPI,Paid\nINV-2026-1050,Aarav Singh,11/09/2026,600,Due,Unsettled\nINV-2026-1051,Meera Verma,10/09/2026,250,Card,Paid\n';
          filename += '.csv';
        } else {
          content = JSON.stringify([
            { id: 'INV-2026-1049', patient: 'Riya Sharma', date: '12/09/2026', amount: 850, method: 'UPI', status: 'Paid' },
            { id: 'INV-2026-1050', patient: 'Aarav Singh', date: '11/09/2026', amount: 600, method: 'Due', status: 'Unsettled' }
          ], null, 2);
          filename += '.json';
        }
      } else if (dataset === 'patients') {
        if (format === 'csv') {
          content = 'UHID,Name,Mobile,Registered Date,Total Visits\nUHID-1001,Ananya Sharma,9876501234,01/09/2026,3\nUHID-1002,Karan Mehra,9876511223,04/09/2026,1\n';
          filename += '.csv';
        } else {
          content = JSON.stringify([
            { uhid: 'UHID-1001', name: 'Ananya Sharma', phone: '9876501234', registered: '01/09/2026', visits: 3 }
          ], null, 2);
          filename += '.json';
        }
      } else {
        content = 'ID,Title,Category,Amount,Date\nEXP-101,Vacutainer Tubes,Consumables,3500,13/09/2026\nEXP-102,Biochemistry Reagents,Reagents,8200,11/09/2026\n';
        filename += '.csv';
      }

      // Trigger browser download
      const blob = new Blob([content], { type: format === 'csv' ? 'text/csv;charset=utf-8;' : 'application/json' });
      const url = URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.href = url;
      link.setAttribute('download', filename);
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);

      setIsExporting(false);
      setDownloadSuccess(true);
      setTimeout(() => setDownloadSuccess(false), 3000);
    }, 800);
  };

  return (
    <div className="business-page">
      <div style={{ marginBottom: '1.25rem' }}>
        <h2 style={{ margin: '0 0 0.25rem 0' }}>Data Export & Compliance Archives</h2>
        <p style={{ margin: 0, fontSize: '0.875rem', color: '#64748b' }}>
          Extract structured audit data for accounting, compliance reports, and tax reconciliation.
        </p>
      </div>

      <div style={{
        backgroundColor: '#ffffff',
        borderRadius: '12px',
        border: '1px solid #e2e8f0',
        padding: '1.75rem',
        maxWidth: '640px'
      }}>
        <form onSubmit={handleExport} style={{ display: 'flex', flexDirection: 'column', gap: '1.25rem' }}>
          <div>
            <label style={{ display: 'block', fontSize: '0.875rem', fontWeight: '600', marginBottom: '0.4rem', color: '#334155' }}>
              Select Data Archive to Export
            </label>
            <select
              value={dataset}
              onChange={e => setDataset(e.target.value)}
              style={{ width: '100%', padding: '0.65rem 0.85rem', borderRadius: '6px', border: '1px solid #cbd5e1', fontSize: '0.9rem', boxSizing: 'border-box' }}
            >
              <option value="bills">Billing, Invoices & Cashier Shift Ledgers</option>
              <option value="patients">Patient Demographics & Medical UHID Registry</option>
              <option value="reports">Diagnostic Lab Test Reports & Findings</option>
              <option value="expenses">Operational Expenses & Supplier Ledger</option>
            </select>
          </div>

          <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '1rem' }}>
            <div>
              <label style={{ display: 'block', fontSize: '0.875rem', fontWeight: '500', marginBottom: '0.4rem', color: '#334155' }}>
                From Date
              </label>
              <input
                type="date"
                value={fromDate}
                onChange={e => setFromDate(e.target.value)}
                style={{ width: '100%', padding: '0.6rem 0.75rem', borderRadius: '6px', border: '1px solid #cbd5e1', fontSize: '0.85rem', boxSizing: 'border-box' }}
              />
            </div>
            <div>
              <label style={{ display: 'block', fontSize: '0.875rem', fontWeight: '500', marginBottom: '0.4rem', color: '#334155' }}>
                To Date
              </label>
              <input
                type="date"
                value={toDate}
                onChange={e => setToDate(e.target.value)}
                style={{ width: '100%', padding: '0.6rem 0.75rem', borderRadius: '6px', border: '1px solid #cbd5e1', fontSize: '0.85rem', boxSizing: 'border-box' }}
              />
            </div>
          </div>

          <div>
            <label style={{ display: 'block', fontSize: '0.875rem', fontWeight: '500', marginBottom: '0.4rem', color: '#334155' }}>
              Export File Format
            </label>
            <div style={{ display: 'flex', gap: '1rem' }}>
              <label style={{ display: 'flex', alignItems: 'center', gap: '0.4rem', fontSize: '0.85rem', cursor: 'pointer' }}>
                <input
                  type="radio"
                  name="format"
                  value="csv"
                  checked={format === 'csv'}
                  onChange={() => setFormat('csv')}
                />
                CSV Spreadsheet (.csv - Excel, Google Sheets)
              </label>
              <label style={{ display: 'flex', alignItems: 'center', gap: '0.4rem', fontSize: '0.85rem', cursor: 'pointer' }}>
                <input
                  type="radio"
                  name="format"
                  value="json"
                  checked={format === 'json'}
                  onChange={() => setFormat('json')}
                />
                JSON Data Document (.json)
              </label>
            </div>
          </div>

          {downloadSuccess && (
            <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem', color: '#15803d', fontSize: '0.875rem', backgroundColor: '#f0fdf4', padding: '0.75rem', borderRadius: '6px', border: '1px solid #bbf7d0' }}>
              <CheckCircleIcon style={{ width: '18px' }} />
              Export file generated and downloaded to your device!
            </div>
          )}

          <div style={{ display: 'flex', justifyContent: 'flex-start', marginTop: '0.5rem' }}>
            <button
              type="submit"
              disabled={isExporting}
              style={{
                display: 'inline-flex',
                alignItems: 'center',
                gap: '0.5rem',
                backgroundColor: '#15803d',
                color: '#ffffff',
                border: 'none',
                padding: '0.75rem 1.4rem',
                borderRadius: '8px',
                fontWeight: '600',
                fontSize: '0.9rem',
                cursor: 'pointer'
              }}
            >
              <DocumentArrowDownIcon style={{ width: '20px' }} />
              {isExporting ? 'Generating Export...' : 'Generate & Download Export'}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
}

import React, { useState } from 'react';
import { CheckCircleIcon, ChatBubbleBottomCenterTextIcon, CheckIcon } from '@heroicons/react/24/outline';
import './BusinessShared.css';

export default function DueReports() {
  const [dues, setDues] = useState([
    { id: 'BILL-401', patient: 'Karan Mehra', phone: '9876511223', test: 'Liver Function Test + Lipid', total: 1550, paid: 1000, due: 550, date: '12/09/2026' },
    { id: 'BILL-398', patient: 'Sunita Yadav', phone: '9812345678', test: 'Thyroid Profile Comprehensive', total: 800, paid: 400, due: 400, date: '10/09/2026' },
    { id: 'BILL-385', patient: 'Vikram Joshi', phone: '9798765432', test: 'Digital X-Ray Chest PA View', total: 400, paid: 0, due: 400, date: '08/09/2026' }
  ]);

  const [dateRange, setDateRange] = useState('14/08/2026 - 13/09/2026');

  const totalDueAmount = dues.reduce((acc, curr) => acc + curr.due, 0);

  const handleSendReminder = (patient, phone) => {
    alert(`SMS payment reminder dispatched to ${patient} (${phone})!`);
  };

  const handleClearDue = (id) => {
    setDues(dues.filter(d => d.id !== id));
    alert('Payment recorded and due cleared successfully.');
  };

  return (
    <div className="business-page">
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '1rem', flexWrap: 'wrap', gap: '0.75rem' }}>
        <div>
          <h2 style={{ margin: '0 0 0.25rem 0' }}>Due Reports & Patient Balances</h2>
          <p style={{ margin: 0, fontSize: '0.875rem', color: '#64748b' }}>Monitor pending balances, dispatch SMS reminders, and reconcile payments.</p>
        </div>
        <div className="b-date-picker" style={{ margin: 0 }}>
          <input 
            type="text" 
            value={dateRange} 
            onChange={e => setDateRange(e.target.value)} 
            style={{ padding: '0.5rem', borderRadius: '6px', border: '1px solid #cbd5e1' }}
          />
        </div>
      </div>

      {/* Summary */}
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(200px, 1fr))', gap: '1rem', marginBottom: '1.25rem' }}>
        <div style={{ background: '#ffffff', padding: '1rem', borderRadius: '8px', border: '1px solid #e2e8f0' }}>
          <span style={{ fontSize: '0.8rem', color: '#64748b' }}>Outstanding Patient Dues</span>
          <div style={{ fontSize: '1.4rem', fontWeight: '700', color: '#dc2626', marginTop: '0.2rem' }}>Rs. {totalDueAmount}</div>
        </div>
        <div style={{ background: '#ffffff', padding: '1rem', borderRadius: '8px', border: '1px solid #e2e8f0' }}>
          <span style={{ fontSize: '0.8rem', color: '#64748b' }}>Unsettled Cases</span>
          <div style={{ fontSize: '1.4rem', fontWeight: '700', color: '#0f172a', marginTop: '0.2rem' }}>{dues.length} Cases</div>
        </div>
      </div>

      {dues.length === 0 ? (
        <div className="b-empty-state">
          <div className="b-empty-icon-box">
            <CheckCircleIcon className="b-empty-icon" />
          </div>
          <p>All dues are cleared.</p>
        </div>
      ) : (
        <div style={{ backgroundColor: '#ffffff', borderRadius: '8px', border: '1px solid #e2e8f0', overflow: 'hidden' }}>
          <table style={{ width: '100%', borderCollapse: 'collapse', textAlign: 'left', fontSize: '0.85rem' }}>
            <thead>
              <tr style={{ backgroundColor: '#f8fafc', borderBottom: '1px solid #e2e8f0' }}>
                <th style={{ padding: '0.75rem 1rem' }}>BILL ID</th>
                <th style={{ padding: '0.75rem 1rem' }}>PATIENT NAME</th>
                <th style={{ padding: '0.75rem 1rem' }}>CONTACT</th>
                <th style={{ padding: '0.75rem 1rem' }}>INVESTIGATIONS</th>
                <th style={{ padding: '0.75rem 1rem' }}>DATE</th>
                <th style={{ padding: '0.75rem 1rem' }}>TOTAL</th>
                <th style={{ padding: '0.75rem 1rem' }}>DUE AMOUNT</th>
                <th style={{ padding: '0.75rem 1rem' }}>ACTIONS</th>
              </tr>
            </thead>
            <tbody>
              {dues.map(item => (
                <tr key={item.id} style={{ borderBottom: '1px solid #f1f5f9' }}>
