                          fontSize: '0.75rem',
                          fontWeight: '600',
                          color: '#334155',
                          cursor: 'pointer'
                        }}
                      >
                        <ChatBubbleBottomCenterTextIcon style={{ width: '14px' }} /> SMS Reminder
                      </button>
                      <button
                        type="button"
                        onClick={() => handleClearDue(item.id)}
                        style={{
                          display: 'inline-flex',
                          alignItems: 'center',
                          gap: '0.25rem',
