                    <div style={{ fontSize: '0.95rem', fontWeight: '700', color: '#0f172a' }}>₹ {lab.priceList.lipid}</div>
                  </div>
                  <div>
                    <span style={{ fontSize: '0.75rem', color: '#64748b' }}>Fasting Sugar</span>
