                  <div>
                    <span style={{ fontSize: '0.75rem', color: '#64748b' }}>Thyroid (T3/T4/TSH)</span>
                    <div style={{ fontSize: '0.95rem', fontWeight: '700', color: '#0f172a' }}>₹ {lab.priceList.thyroid}</div>
