        )}

        {/* Message bubble */}
        <div
          style={{
            background: isUser
              ? 'linear-gradient(135deg, #15803d, #059669)'
              : 'white',
            color: isUser ? 'white' : '#0f172a',
            border: isUser ? 'none' : '1px solid #e2e8f0',
            borderRadius: isUser ? '18px 18px 4px 18px' : '4px 18px 18px 18px',
