  transition: all 0.2s ease;
  z-index: 50;
}

.dashboard-home-support-pill:hover {
  background-color: #f0fdf4;
  border-color: #bbf7d0;
  transform: translateY(-2px);
  box-shadow: 0 6px 18px rgba(21, 128, 61, 0.15);
}

.dashboard-home-support-icon {
  width: 22px;
  height: 22px;
  color: #15803d;
}

