  gap: 1.5rem;
}

.lab-header-row {
  display: flex;
  align-items: baseline;
  gap: 1rem;
}

.lab-view-container h2 {
  font-size: 1.5rem;
  margin: 0;
  color: #111827;
}

.lab-help-banner {
  background-color: #f8fafc;
  padding: 0.75rem 1.25rem;
