import LabSetuVideoPlayer from '../components/common/LabSetuVideoPlayer';
import Footer from '../components/common/Footer';
import './MainLayout.css';
import { 
  MagnifyingGlassIcon, 
  QuestionMarkCircleIcon, 
  Cog6ToothIcon, 
  PlayCircleIcon, 
  BellIcon, 
  UserCircleIcon,
  ChevronDownIcon,
  ChevronUpIcon,
  ChartBarIcon,
  ClipboardDocumentListIcon,
  BeakerIcon,
  ComputerDesktopIcon,
  CameraIcon,
  IdentificationIcon,
  BuildingOfficeIcon,
  ListBulletIcon,
  DocumentTextIcon,
  StarIcon,
  ChatBubbleLeftIcon,
  ClipboardDocumentIcon,
  CheckBadgeIcon,
  CalendarIcon,
  WalletIcon,
  DocumentDuplicateIcon,
  UsersIcon,
  ArrowDownTrayIcon,
  ReceiptRefundIcon,
  GlobeAltIcon,
  FilmIcon,
  UserGroupIcon,
  ArrowsRightLeftIcon,
  UserPlusIcon,
  DocumentCheckIcon,
  ArchiveBoxIcon,
  ChartPieIcon,
  Squares2X2Icon,
  InformationCircleIcon,
  CalculatorIcon,
  DocumentIcon,
  PencilSquareIcon,
  ShieldCheckIcon,
  UserIcon,
  CurrencyRupeeIcon,
  EnvelopeIcon,
  PlusCircleIcon,
  XMarkIcon,
  Bars3Icon,
  ArrowRightOnRectangleIcon,
  SparklesIcon
} from '@heroicons/react/24/outline';

export default function MainLayout() {
  const { currentUser, logout, updateCurrentUser } = useAuth();
  const location = useLocation();
  const navigate = useNavigate();

  const [isMobileNavOpen, setIsMobileNavOpen] = useState(false);
  const [isBusinessExpanded, setIsBusinessExpanded] = useState(false);
  const [isCasesExpanded, setIsCasesExpanded] = useState(false);
  const [isLabExpanded, setIsLabExpanded] = useState(false);
  const [isUsgExpanded, setIsUsgExpanded] = useState(false);
  const [isXrayExpanded, setIsXrayExpanded] = useState(false);
  const [isManageExpanded, setIsManageExpanded] = useState(false);
  const [isSetupExpanded, setIsSetupExpanded] = useState(false);
  const [isUserMenuExpanded, setIsUserMenuExpanded] = useState(false);
  const [isNotificationsOpen, setIsNotificationsOpen] = useState(false);
  const [isHelpOpen, setIsHelpOpen] = useState(false);
  const [isVideoOpen, setIsVideoOpen] = useState(false);
  const [legalModal, setLegalModal] = useState(null);
  const [isNewLabModalOpen, setIsNewLabModalOpen] = useState(false);
  const [isEmailPrefModalOpen, setIsEmailPrefModalOpen] = useState(false);
  const [isNewNavEnabled, setIsNewNavEnabled] = useState(true);
  const [searchQuery, setSearchQuery] = useState('');
  const [copiedLabId, setCopiedLabId] = useState(false);

  const [notifications, setNotifications] = useState([
    { id: 1, title: 'Sample Collected', desc: 'Sample collected for Patient Riya Sharma (CBC).', time: '10 mins ago', read: false },
    { id: 2, title: 'Bill Generated', desc: 'New bill #INV-2026-1051 generated by Reception.', time: '45 mins ago', read: false },
    { id: 3, title: 'Backup Completed', desc: 'Daily automated cloud backup finished successfully.', time: '2 hours ago', read: true }
  ]);

  const setupDropdownRef = useRef(null);
  const userMenuRef = useRef(null);
  const notifRef = useRef(null);

  // Close dropdown when clicking outside
  useEffect(() => {
    function handleClickOutside(event) {
      if (setupDropdownRef.current && !setupDropdownRef.current.contains(event.target)) {
        setIsSetupExpanded(false);
      }
      if (userMenuRef.current && !userMenuRef.current.contains(event.target)) {
        setIsUserMenuExpanded(false);
      }
      if (notifRef.current && !notifRef.current.contains(event.target)) {
        setIsNotificationsOpen(false);
      }
    }
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  useEffect(() => {
    const pathParts = location.pathname.split('/').filter(Boolean);
    if (pathParts.length > 1) {
      const lastPart = pathParts[pathParts.length - 1];
      const title = lastPart.split('-').map(word => word.charAt(0).toUpperCase() + word.slice(1)).join(' ');
      document.title = `LabSetu - ${title}`;
    } else {
      document.title = 'LabSetu';
    }
    setIsMobileNavOpen(false);
  }, [location]);

  const handleCopyLabId = () => {
    navigator.clipboard?.writeText(currentUser?.labId || '61326885');
    setCopiedLabId(true);
    setTimeout(() => setCopiedLabId(false), 2000);
  };

  const handleLogout = async () => {
    localStorage.removeItem('labsetu_authority_session');
    localStorage.removeItem('labsetu_auth');
    sessionStorage.clear();
    await logout('authority');
    navigate('/login');
  };

  const handleSearchSubmit = (e) => {
    e.preventDefault();
    if (searchQuery.trim()) {
      navigate(`/app/lab/search-reports?q=${encodeURIComponent(searchQuery.trim())}`);
      setSearchQuery('');
    }
  };

  const markAllRead = () => {
    setNotifications(notifications.map(n => ({ ...n, read: true })));
  };

  const unreadCount = notifications.filter(n => !n.read).length;

  return (
    <div className="layout-container">
      {/* Top Header */}
      <header className="layout-header">
        <div className="layout-header-left">
          <button 
            type="button" 
            className="layout-mobile-hamburger-btn" 
            onClick={() => setIsMobileNavOpen(!isMobileNavOpen)}
            aria-label="Toggle navigation menu"
          >
            {isMobileNavOpen ? <XMarkIcon style={{ width: '22px', height: '22px' }} /> : <Bars3Icon style={{ width: '22px', height: '22px' }} />}
          </button>
          <img src={logo} alt="LabSetu Logo" className="layout-logo" />
          <span className="layout-brand">Lab<span className="layout-brand-highlight">Setu</span></span>
          <span className="layout-badge" title="Laboratory Information Management System">LIMS</span>
        </div>

        <div className="layout-header-center">
          <form onSubmit={handleSearchSubmit} className="layout-search-wrapper">
            <MagnifyingGlassIcon className="layout-icon search-icon" />
            <input 
              type="text" 
              placeholder="Search any bills, reports, patient records..." 
              className="layout-search-input" 
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
            />
          </form>
        </div>

        <div className="layout-header-right">
          <button 
            type="button" 
            className="layout-header-link" 
            style={{ background: 'none', border: 'none', cursor: 'pointer' }}
            onClick={() => setIsHelpOpen(true)}
          >
            <QuestionMarkCircleIcon className="layout-icon" /> Help
          </button>

          {/* Setup Dropdown */}
          <div style={{position: 'relative'}} ref={setupDropdownRef}>
            <button 
              className="layout-header-link" 
              style={{background: 'none', border: 'none', cursor: 'pointer'}}
              onClick={() => setIsSetupExpanded(!isSetupExpanded)}
            >
              <Cog6ToothIcon className="layout-icon" /> Setup <ChevronDownIcon style={{width:'16px'}} />
            </button>

            <div className={`layout-setup-dropdown ${isSetupExpanded ? 'active' : ''}`}>
              <NavLink to="/app/setup/kyc" onClick={() => setIsSetupExpanded(false)}><IdentificationIcon/> KYC</NavLink>
              <NavLink to="/app/setup/center-details" onClick={() => setIsSetupExpanded(false)}><BuildingOfficeIcon/> Center details</NavLink>
              <NavLink to="/app/setup/ratelist" onClick={() => setIsSetupExpanded(false)}><ListBulletIcon/> Ratelist</NavLink>
              <NavLink to="/app/setup/letterhead" onClick={() => setIsSetupExpanded(false)}><DocumentTextIcon/> Letterhead</NavLink>
              <NavLink to="/app/setup/google-review" onClick={() => setIsSetupExpanded(false)}><StarIcon/> Build google review</NavLink>
              <NavLink to="/app/setup/sms" onClick={() => setIsSetupExpanded(false)}><ChatBubbleLeftIcon/> SMS</NavLink>
              <NavLink to="/app/setup/case-reg-no" onClick={() => setIsSetupExpanded(false)}><ClipboardDocumentIcon/> Case reg. no.</NavLink>
              <NavLink to="/app/setup/panels" onClick={() => setIsSetupExpanded(false)}><BeakerIcon/> Panels</NavLink>
              <NavLink to="/app/setup/proofread" onClick={() => setIsSetupExpanded(false)}><CheckBadgeIcon/> Proofread</NavLink>
            </div>
          </div>

          <button 
            type="button" 
            className="layout-header-link" 
            style={{ background: 'none', border: 'none', cursor: 'pointer' }}
            onClick={() => setIsVideoOpen(true)}
          >
            <PlayCircleIcon className="layout-icon" /> Watch Video
          </button>

          {/* Notifications Button */}
          <div style={{ position: 'relative' }} ref={notifRef}>
            <button 
              type="button" 
              className="layout-icon-btn" 
              onClick={() => setIsNotificationsOpen(!isNotificationsOpen)}
              title="Notifications"
            >
              <BellIcon className="layout-icon" />
              {unreadCount > 0 && (
                <span className="layout-notif-badge">{unreadCount}</span>
              )}
            </button>

            {isNotificationsOpen && (
              <div className="layout-setup-dropdown active" style={{ right: 0, width: '300px', padding: '0.5rem 0' }}>
                <div style={{ display: 'flex', justifyContent: 'space-between', padding: '0.5rem 1rem', borderBottom: '1px solid #f1f5f9', fontSize: '0.85rem' }}>
                  <strong>Lab Notifications</strong>
                  {unreadCount > 0 && (
                    <button type="button" onClick={markAllRead} style={{ background: 'none', border: 'none', color: '#15803d', fontSize: '0.75rem', cursor: 'pointer' }}>
                      Mark all read
                    </button>
                  )}
                </div>
