        lastLogin: 'Today',
        status: 'Trusted'
      }]);
      setDeviceInput('');
      setIsModalOpen(false);
    }
  };

  const handleRevoke = (id) => {
    if (window.confirm('Revoke access for this browser session? The session will be instantly logged out.')) {
      setBrowsers(browsers.filter(b => b.id !== id));
    }
  };

  return (
    <div className="lab-view-container">
      <div className="lab-header-row" style={{justifyContent: 'space-between'}}>
        <div>
          <h2>Browser Security & Whitelisted Devices</h2>
          <p style={{ margin: '0.2rem 0 0 0', fontSize: '0.85rem', color: '#64748b' }}>Restrict LabSetu authority workspace to authorized laboratory devices.</p>
        </div>
        <button type="button" className="lab-btn lab-btn-blue" onClick={() => setIsModalOpen(true)}>
          <PlusIcon className="lab-btn-icon"/> Add allowed browser
        </button>
      </div>

      <table className="lab-data-table">
        <thead>
          <tr>
            <th>DEVICE / BROWSER SIGNATURE</th>
            <th>LAST LOGIN</th>
            <th>STATUS</th>
            <th>SECURITY ACTION</th>
          </tr>
        </thead>
        <tbody>
          {browsers.map(b => (
            <tr key={b.id} className="lab-hover-interactive">
              <td><strong>{b.device}</strong></td>
              <td>{b.lastLogin}</td>
              <td>
                <span style={{ backgroundColor: '#dcfce7', color: '#15803d', padding: '0.2rem 0.5rem', borderRadius: '4px', fontSize: '0.75rem', fontWeight: '600' }}>
                  {b.status}
                </span>
              </td>
              <td>
                <button 
                  type="button" 
                  className="lab-link-btn" 
                  style={{color:'#ef4444', display: 'inline-flex', alignItems: 'center', gap: '0.2rem'}}
                  onClick={() => handleRevoke(b.id)}
                >
                  <TrashIcon className="lab-small-icon"/> Revoke Access
                </button>
              </td>
            </tr>
          ))}
        </tbody>
      </table>

      {isModalOpen && (
        <div style={{ position: 'fixed', inset: 0, backgroundColor: 'rgba(0,0,0,0.5)', display: 'flex', alignItems: 'center', justifyContent: 'center', zIndex: 1000, padding: '1rem' }} onClick={() => setIsModalOpen(false)}>
          <div style={{ backgroundColor: '#ffffff', borderRadius: '12px', maxWidth: '440px', width: '100%', padding: '1.5rem' }} onClick={e => e.stopPropagation()}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '1rem' }}>
              <h3 style={{ margin: 0, fontSize: '1.15rem' }}>Authorize Trusted Browser</h3>
              <button type="button" onClick={() => setIsModalOpen(false)} style={{ background: 'none', border: 'none', cursor: 'pointer' }}>
                <XMarkIcon style={{ width: '20px' }} />
              </button>
            </div>
            <form onSubmit={handleAdd} style={{ display: 'flex', flexDirection: 'column', gap: '0.85rem' }}>
              <div>
                <label style={{ display: 'block', fontSize: '0.85rem', marginBottom: '0.35rem', fontWeight: '500' }}>Browser / Device Identifier</label>
                <input required type="text" placeholder="e.g. Chrome (Windows) - Phlebotomy Tablet" value={deviceInput} onChange={e => setDeviceInput(e.target.value)} style={{ width: '100%', padding: '0.6rem', border: '1px solid #cbd5e1', borderRadius: '6px', boxSizing: 'border-box' }} />
              </div>
              <div style={{ display: 'flex', justifyContent: 'flex-end', gap: '0.5rem', marginTop: '0.5rem' }}>
                <button type="button" onClick={() => setIsModalOpen(false)} style={{ padding: '0.55rem 1rem', borderRadius: '6px', border: '1px solid #cbd5e1', background: '#ffffff', cursor: 'pointer' }}>Cancel</button>
                <button type="submit" style={{ padding: '0.55rem 1rem', borderRadius: '6px', border: 'none', background: '#15803d', color: '#ffffff', fontWeight: '600', cursor: 'pointer' }}>Whitelist Browser</button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}

import React, { useState, useEffect } from 'react';
import '../lab/LabShared.css';
import { supabase } from '../../lib/supabase';
import {
  PlusIcon,
  PencilIcon,
  XMarkIcon,
  EnvelopeIcon,
  CheckCircleIcon,
  ClockIcon,
  PaperAirplaneIcon,
  TrashIcon,
  ShieldCheckIcon,
  SparklesIcon
} from '@heroicons/react/24/outline';

export default function DoctorAccess() {
  const initialDoctors = [
    {
      id: 'doc-1',
      name: 'Dr. A. K. Smith (MD Pathology)',
      email: 'dr.smith@labsetu.health',
      access: 'Full Access (Reports, Sign-off & Patient History)',
      status: 'Active',
      invitedAt: '10/09/2026',
      lastLogin: '13/09/2026 10:15 AM'
    },
    {
      id: 'doc-2',
      name: 'Dr. Meera Jones (MD Radiology)',
      email: 'dr.jones@delhi-radiology.in',
      access: 'View Only (Radiology & X-Ray Scans)',
      status: 'Pending Activation',
      invitedAt: '12/10/2026',
      lastLogin: 'Pending User Activation'
    }
  ];

  const [doctors, setDoctors] = useState(() => {
    try {
      const saved = localStorage.getItem('labsetu_doctor_invites');
      return saved ? JSON.parse(saved) : initialDoctors;
    } catch {
      return initialDoctors;
    }
  });

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingDoc, setEditingDoc] = useState(null);
  const [toast, setToast] = useState('');
  const [form, setForm] = useState({
    name: '',
    email: '',
    access: 'Full Access (Reports, Sign-off & Patient History)'
  });

  const showToast = (msg) => {
    setToast(msg);
    setTimeout(() => setToast(''), 4000);
  };

  const persistDoctors = (updated) => {
    setDoctors(updated);
    try {
      localStorage.setItem('labsetu_doctor_invites', JSON.stringify(updated));
    } catch {}
  };

  // Sync Supabase staff_invites table
  useEffect(() => {
    const fetchInvites = async () => {
      try {
        const { data, error } = await supabase
          .from('staff_invites')
          .select('*')
          .eq('role', 'doctor');

        if (!error && Array.isArray(data) && data.length > 0) {
          const mapped = data.map((d) => ({
            id: d.id,
            name: d.name,
            email: d.email,
            access: d.access_level,
            status: d.status,
            invitedAt: new Date(d.invited_at).toLocaleDateString(),
            lastLogin: d.status === 'Active' ? 'Activated' : 'Pending User Activation'
          }));
          // Merge with local state
          setDoctors(prev => {
            const combined = [...prev];
            mapped.forEach(m => {
              if (!combined.some(c => c.email === m.email)) {
                combined.push(m);
              }
            });
            return combined;
          });
        }
      } catch (e) {
        console.warn('Supabase doctor invites sync fallback:', e);
      }
    };

    fetchInvites();
  }, []);

  const handleOpenGrant = () => {
    setEditingDoc(null);
    setForm({
      name: '',
      email: '',
      access: 'Full Access (Reports, Sign-off & Patient History)'
    });
    setIsModalOpen(true);
  };

  const handleOpenEdit = (doc) => {
    setEditingDoc(doc);
    setForm({
      name: doc.name,
      email: doc.email,
      access: doc.access
    });
    setIsModalOpen(true);
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    if (editingDoc) {
      const updated = doctors.map(d =>
        d.id === editingDoc.id
          ? { ...d, name: form.name, email: form.email, access: form.access }
          : d
      );
      persistDoctors(updated);
      showToast(`Updated doctor profile for ${form.name}.`);
    } else {
      const newDoc = {
        id: `doc-${Date.now()}`,
        name: form.name,
        email: form.email,
        access: form.access,
        status: 'Pending Activation',
        invitedAt: new Date().toLocaleDateString(),
        lastLogin: 'Pending User Activation'
      };
      persistDoctors([newDoc, ...doctors]);

      // Push to Supabase staff_invites
      try {
        supabase.from('staff_invites').insert({
          name: form.name,
          email: form.email,
          role: 'doctor',
          access_level: form.access,
          status: 'Pending Activation'
        }).then(({ error }) => {
          if (error) console.warn('Supabase invite insert error:', error);
        });
      } catch (err) {
        console.warn('Supabase fallback:', err);
      }

      showToast(`Invitation email dispatched with secure activation link to ${form.email}.`);
    }
    setIsModalOpen(false);
  };

  const handleResendInvite = (doc) => {
    showToast(`Invitation re-dispatched to ${doc.email} with secure single-use token.`);
  };

  const handleSimulateActivation = (doc) => {
    const updated = doctors.map(d => {
      if (d.id === doc.id) {
        return {
          ...d,
          status: 'Active',
          lastLogin: `Active Now (Activated ${new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })})`
        };
      }
      return d;
    });
    persistDoctors(updated);

    // Update in Supabase
    try {
      supabase
        .from('staff_invites')
        .update({ status: 'Active', activated_at: new Date().toISOString() })
        .eq('email', doc.email)
        .then(() => {});
    } catch {}

    showToast(`Access activated successfully! ${doc.name} can now sign into LIMS.`);
  };

  const handleDelete = (docId) => {
    if (window.confirm('Revoke access for this physician?')) {
      const updated = doctors.filter(d => d.id !== docId);
      persistDoctors(updated);
      showToast('Doctor credentials and access token revoked.');
    }
  };

  return (
    <div className="lab-view-container">
      {/* Toast Notification */}
      {toast && (
        <div style={{
          position: 'fixed',
          top: '20px',
          right: '20px',
          background: '#064e3b',
          color: 'white',
          padding: '0.85rem 1.25rem',
          borderRadius: '8px',
          boxShadow: '0 4px 12px rgba(0,0,0,0.15)',
          zIndex: 9999,
          display: 'flex',
          alignItems: 'center',
          gap: '0.5rem',
          fontSize: '0.9rem',
          fontWeight: '500'
        }}>
          <CheckCircleIcon style={{ width: '20px', color: '#34d399' }} />
          <span>{toast}</span>
        </div>
      )}

      {/* Header */}
      <div className="lab-header-row" style={{ justifyContent: 'space-between', alignItems: 'flex-start' }}>
        <div>
          <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem', marginBottom: '0.2rem' }}>
            <span style={{
              background: '#ecfdf5',
              color: '#059669',
              fontSize: '0.75rem',
              fontWeight: '700',
              padding: '0.15rem 0.5rem',
              borderRadius: '4px',
              border: '1px solid #a7f3d0'
            }}>
              ROLE-BASED ACCESS CONTROL
            </span>
          </div>
          <h2 style={{ margin: '0 0 0.25rem' }}>Doctor Portal &amp; Physician Referral Access</h2>
          <p style={{ margin: 0, fontSize: '0.85rem', color: '#64748b' }}>
            Invite medical officers, radiologists, and consulting pathologists via secure email verification tokens
          </p>
        </div>

        <button type="button" className="lab-btn lab-btn-blue" onClick={handleOpenGrant}>
          <PlusIcon className="lab-btn-icon" /> Invite New Doctor
        </button>
      </div>

      {/* Table */}
      <div style={{ background: 'white', borderRadius: '10px', border: '1px solid #e2e8f0', overflow: 'hidden', marginTop: '1rem' }}>
        <table className="lab-data-table" style={{ margin: 0 }}>
          <thead>
            <tr>
              <th>DOCTOR NAME &amp; DEGREE</th>
              <th>WORK EMAIL</th>
              <th>ACCESS LEVEL</th>
              <th>STATUS</th>
              <th>INVITED / LAST LOGIN</th>
              <th style={{ textAlign: 'right' }}>ACTIONS</th>
            </tr>
          </thead>
          <tbody>
            {doctors.map(doc => {
              const isPending = doc.status === 'Pending Activation';

              return (
                <tr key={doc.id} className="lab-hover-interactive">
                  <td>
                    <strong>{doc.name}</strong>
                  </td>
                  <td>
                    <span style={{ color: '#475569', fontSize: '0.85rem' }}>{doc.email}</span>
                  </td>
                  <td>
                    <span style={{
                      background: '#f1f5f9',
                      padding: '0.2rem 0.5rem',
                      borderRadius: '4px',
                      fontSize: '0.78rem',
                      color: '#334155',
                      fontWeight: '500'
                    }}>
                      {doc.access}
                    </span>
                  </td>
                  <td>
                    {isPending ? (
                      <span style={{
                        display: 'inline-flex',
                        alignItems: 'center',
                        gap: '0.3rem',
                        background: '#fef3c7',
                        color: '#92400e',
                        padding: '0.2rem 0.6rem',
                        borderRadius: '20px',
                        fontSize: '0.75rem',
                        fontWeight: '700'
                      }}>
                        <ClockIcon style={{ width: '13px' }} />
                        Pending Activation
                      </span>
                    ) : (
                      <span style={{
                        display: 'inline-flex',
                        alignItems: 'center',
                        gap: '0.3rem',
                        background: '#dcfce7',
                        color: '#15803d',
                        padding: '0.2rem 0.6rem',
                        borderRadius: '20px',
                        fontSize: '0.75rem',
                        fontWeight: '700'
                      }}>
                        <CheckCircleIcon style={{ width: '13px' }} />
                        Active
                      </span>
                    )}
                  </td>
                  <td style={{ fontSize: '0.82rem', color: '#64748b' }}>
                    {doc.lastLogin}
                  </td>
                  <td style={{ textAlign: 'right' }}>
                    <div style={{ display: 'inline-flex', gap: '0.4rem', alignItems: 'center' }}>
                      {isPending && (
                        <>
                          <button
                            type="button"
                            title="Resend invitation email"
                            onClick={() => handleResendInvite(doc)}
                            style={{
                              background: '#f0fdf4',
                              border: '1px solid #86efac',
                              color: '#15803d',
                              padding: '0.25rem 0.5rem',
                              borderRadius: '6px',
                              fontSize: '0.75rem',
                              fontWeight: '600',
                              cursor: 'pointer'
                            }}
                          >
                            Resend Invite
                          </button>

                          <button
                            type="button"
                            title="Evaluator shortcut: simulate clicking email activation link"
                            onClick={() => handleSimulateActivation(doc)}
                            style={{
                              background: '#ecfdf5',
                              border: '1px solid #059669',
                              color: '#059669',
                              padding: '0.25rem 0.55rem',
                              borderRadius: '6px',
                              fontSize: '0.75rem',
                              fontWeight: '700',
                              cursor: 'pointer'
                            }}
                          >
                            ⚡ Simulate Activation
                          </button>
                        </>
                      )}

                      <button
                        type="button"
                        className="lab-link-btn"
                        onClick={() => handleOpenEdit(doc)}
                        style={{ padding: '0.25rem 0.5rem' }}
                      >
                        <PencilIcon className="lab-small-icon" /> Edit
                      </button>

                      <button
                        type="button"
                        onClick={() => handleDelete(doc.id)}
                        style={{ background: 'none', border: 'none', color: '#ef4444', cursor: 'pointer', padding: '0.25rem' }}
                        title="Revoke access"
                      >
                        <TrashIcon style={{ width: '15px' }} />
                      </button>
                    </div>
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>

      {/* Grant / Edit Modal */}
      {isModalOpen && (
        <div
          style={{
            position: 'fixed',
            inset: 0,
            backgroundColor: 'rgba(0,0,0,0.5)',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            zIndex: 1000,
            padding: '1rem'
          }}
          onClick={() => setIsModalOpen(false)}
        >
          <div
            style={{
              backgroundColor: '#ffffff',
              borderRadius: '14px',
              maxWidth: '480px',
              width: '100%',
              padding: '1.75rem',
              boxShadow: '0 20px 25px -5px rgba(0,0,0,0.2)'
            }}
            onClick={e => e.stopPropagation()}
          >
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '1.25rem', borderBottom: '1px solid #e2e8f0', paddingBottom: '0.75rem' }}>
              <div>
                <h3 style={{ margin: 0, fontSize: '1.2rem', color: '#0f172a' }}>
                  {editingDoc ? 'Edit Doctor Access Level' : 'Invite Doctor to LIMS Portal'}
