                            Resend Invite
                          </button>

                          <button
                            type="button"
                            title="Evaluator shortcut: simulate employee activating account"
                            onClick={() => handleSimulateActivation(emp)}
                            style={{
                              background: '#ecfdf5',
                              border: '1px solid #059669',
                              color: '#059669',
