import React, { useState } from 'react';
import './Letterhead.css';
import { InformationCircleIcon, PrinterIcon, ArrowUpTrayIcon } from '@heroicons/react/24/outline';
import useDemoResource from '../../hooks/useDemoResource';

export default function Letterhead() {
  const { data: config, update: setConfig } = useDemoResource('labsetu_setup_letterhead', {
    headerHeight: '4.60',
    footerHeight: '3.40',
    showBorder: true,
    labName: 'LabSetu Diagnostic Centre',
  });

  const [headerHeight, setHeaderHeight] = useState(config?.headerHeight || '4.60');
  const [footerHeight, setFooterHeight] = useState(config?.footerHeight || '3.40');
  const [labName, setLabName] = useState(config?.labName || 'LabSetu Diagnostic Centre');
  const [showMore, setShowMore] = useState(false);
  const [notice, setNotice] = useState('');

  const handleUpdate = (e) => {
    e.preventDefault();
    setConfig({ headerHeight, footerHeight, labName });
    setNotice('Letterhead margins and settings saved successfully.');
    setTimeout(() => setNotice(''), 3000);
  };

  const handleFileUpload = (e) => {
    const file = e.target.files?.[0];
    if (file) {
      setNotice(`Sample header "${file.name}" uploaded successfully for preview.`);
      setTimeout(() => setNotice(''), 3500);
    }
  };

  return (
    <div>
      <h2 className="setup-page-title">Letterhead Configuration</h2>

      {notice && (
        <div style={{ background: '#dcfce7', color: '#15803d', padding: '0.75rem', borderRadius: '6px', fontSize: '0.9rem', marginBottom: '1.25rem', border: '1px solid #86efac' }}>
          ✓ {notice}
        </div>
      )}

      <div className="letterhead-grid">
        {/* Left: Form */}
        <div>
          <form onSubmit={handleUpdate}>
            <div className="setup-form-group">
              <label className="setup-label">Upload Letterhead Header/Banner</label>
              <input type="file" className="setup-input" accept="image/jpeg,image/png" onChange={handleFileUpload} />
              <p style={{ fontSize: '0.8rem', color: '#6b7280', marginTop: '0.5rem' }}>(Supported file formats: jpeg, jpg, png. Max 400KB)</p>
              <button
                type="button"
                onClick={() => window.print()}
                style={{ color: '#2563eb', fontSize: '0.9rem', textDecoration: 'none', background: 'none', border: 'none', cursor: 'pointer', padding: 0, display: 'inline-flex', alignItems: 'center', gap: '0.25rem', marginTop: '0.25rem' }}
              >
                <PrinterIcon style={{ width: '16px' }} /> Preview Print PDF
              </button>
            </div>

            <p style={{ fontSize: '0.85rem', color: '#374151', marginBottom: '1rem' }}>
              Standard A4 letterhead will be merged into clinical patient reports.
            </p>

            <div style={{ display: 'flex', gap: '1rem', marginBottom: '1.5rem' }}>
              <div className="setup-form-group" style={{ flex: 1 }}>
                <label className="setup-label">Header height</label>
                <div style={{ display: 'flex', alignItems: 'center' }}>
                  <input
                    type="number"
                    step="0.1"
                    min="1"
                    max="10"
                    className="setup-input"
                    value={headerHeight}
                    onChange={(e) => setHeaderHeight(e.target.value)}
                  />
                  <span style={{ marginLeft: '-2.2rem', color: '#6b7280', fontSize: '0.85rem', pointerEvents: 'none' }}>cm</span>
                </div>
              </div>
              <div className="setup-form-group" style={{ flex: 1 }}>
                <label className="setup-label">Footer height</label>
                <div style={{ display: 'flex', alignItems: 'center' }}>
                  <input
                    type="number"
                    step="0.1"
                    min="1"
                    max="10"
                    className="setup-input"
                    value={footerHeight}
                    onChange={(e) => setFooterHeight(e.target.value)}
                  />
                  <span style={{ marginLeft: '-2.2rem', color: '#6b7280', fontSize: '0.85rem', pointerEvents: 'none' }}>cm</span>
                </div>
              </div>
            </div>

            <div
              style={{ marginBottom: '1rem', fontSize: '0.9rem', color: '#2563eb', cursor: 'pointer', userSelect: 'none' }}
              onClick={() => setShowMore(!showMore)}
            >
              {showMore ? 'Fewer settings ▴' : 'More settings ⌄'}
            </div>

            {showMore && (
              <div className="setup-form-group" style={{ background: '#f8fafc', padding: '1rem', borderRadius: '6px', marginBottom: '1rem' }}>
                <label className="setup-label">Centre Title on Reports</label>
                <input
                  type="text"
                  className="setup-input"
                  value={labName}
                  onChange={(e) => setLabName(e.target.value)}
                />
              </div>
            )}

            <button type="submit" className="setup-btn-blue">Update Margins</button>
          </form>
        </div>

        {/* Center: Mockup */}
        <div style={{ display: 'flex', justifyContent: 'center' }}>
          <div className="letterhead-mockup-wrapper">
            <div className="letterhead-success-banner">✓ Letterhead preview in A4 ratio</div>
            <div className="letterhead-paper">
              <div className="letterhead-header" style={{ minHeight: `${Math.max(30, parseFloat(headerHeight || 4.6) * 12)}px` }}>
                <div style={{ fontSize: '1rem', fontWeight: '600' }}>{labName}</div>
                <div style={{ fontSize: '0.8rem', color: '#4b5563' }}>Authorized Diagnostic & Pathology Services</div>
              </div>

              <div className="letterhead-margin-line top-margin">
                <span className="margin-label">Header: {headerHeight} cm</span>
              </div>

              <div className="letterhead-content">
                <div style={{ fontSize: '0.75rem', color: '#9ca3af', textAlign: 'center', marginTop: '1.5rem' }}>
                  — Clinical Report Body Content Area —
                </div>
              </div>

              <div className="letterhead-margin-line bottom-margin">
                <span className="margin-label">Footer: {footerHeight} cm</span>
              </div>

              <div className="letterhead-footer" style={{ minHeight: `${Math.max(20, parseFloat(footerHeight || 3.4) * 8)}px` }}>
                <div style={{ fontSize: '0.6rem', textAlign: 'center' }}>NOT VALID FOR MEDICO LEGAL PURPOSE · COMPUTER GENERATED REPORT</div>
              </div>
            </div>
          </div>
        </div>

        {/* Right: Info */}
        <div>
          <h4 style={{ color: '#2563eb', fontSize: '0.95rem', marginBottom: '1rem' }}>Important information</h4>
          <div className="letterhead-info-box">
            <InformationCircleIcon style={{ width: '20px', flexShrink: 0, color: '#6b7280' }} />
            <span>Please note down the settings before making any changes so that you can always restore the original settings.</span>
          </div>
          <div className="letterhead-info-box">
            <InformationCircleIcon style={{ width: '20px', flexShrink: 0, color: '#6b7280' }} />
            <span>You can upload high-resolution JPG or PNG letterhead artwork (recommended 1000px by 1414px).</span>
          </div>
          <div className="letterhead-info-box">
            <InformationCircleIcon style={{ width: '20px', flexShrink: 0, color: '#6b7280' }} />
            <span>Use a centimeter scale to measure header and footer height printed by your local stationer.</span>
          </div>
        </div>
      </div>
    </div>
  );
}

import React, { useState } from 'react';
import '../lab/LabShared.css';
import { PencilIcon, CheckIcon, XMarkIcon } from '@heroicons/react/24/outline';
import useDemoResource from '../../hooks/useDemoResource';

export default function Proofread() {
  const categories = [
    'Haematology', 'Biochemistry', 'Serology & Immunology',
    'Clinical Pathology', 'Cytology', 'Microbiology', 'Endocrinology', 'Histopathology', 'Others'
  ];

  const initialTestLibrary = {
    'Haematology': [
      {
        id: 'hb',
        name: 'Hemoglobin, Hb (g/dl)',
        ranges: [
          { gender: 'M/F', age: '0D - 21D', val: '17.0 - 23.0' },
          { gender: 'M/F', age: '21D - 10Y', val: '11.2 - 16.5' },
          { gender: 'M', age: '10Y - 120Y', val: '13.0 - 17.0' },
          { gender: 'F', age: '10Y - 120Y', val: '12.0 - 15.0' },
        ]
      },
      {
        id: 'tlc',
        name: 'Total Leukocyte Count, TLC (cumm)',
        ranges: [
          { gender: 'M/F', age: '0D - 14D', val: '9,000.0 - 30,000.0' },
          { gender: 'M/F', age: '15D - 2M', val: '5,000.0 - 21,000.0' },
          { gender: 'M/F', age: '2M - 6Y', val: '5,000.0 - 19,000.0' },
          { gender: 'M/F', age: '6Y - 120Y', val: '4,800.0 - 10,800.0' },
        ]
      },
      {
        id: 'plt',
        name: 'Platelet Count (lakhs/cumm)',
        ranges: [
          { gender: 'M/F', age: 'All ages', val: '1.50 - 4.50' },
        ]
      }
    ],
    'Biochemistry': [
      {
        id: 'fbs',
        name: 'Fasting Blood Sugar (mg/dL)',
        ranges: [
          { gender: 'M/F', age: 'Adults', val: '70.0 - 100.0' },
        ]
      },
      {
        id: 's_chol',
        name: 'Serum Cholesterol (mg/dL)',
        ranges: [
          { gender: 'M/F', age: 'Adults', val: '125.0 - 200.0' },
        ]
      }
    ]
  };

  const { data: testLibrary, update: setTestLibrary } = useDemoResource('labsetu_setup_proofread', initialTestLibrary);
  const [activeCategory, setActiveCategory] = useState('Haematology');
  const [editingTest, setEditingTest] = useState(null);
  const [notice, setNotice] = useState('');

  const currentTests = testLibrary[activeCategory] || [
    {
      id: `${activeCategory.toLowerCase()}_default`,
      name: `${activeCategory} Standard Parameter`,
      ranges: [{ gender: 'M/F', age: 'Adults', val: 'Refer to kit insert' }]
    }
  ];

  const handleSaveEdit = (e) => {
    e.preventDefault();
    const updatedCategoryTests = currentTests.map(t => t.id === editingTest.id ? editingTest : t);
    setTestLibrary({
      ...testLibrary,
      [activeCategory]: updatedCategoryTests
    });
    setEditingTest(null);
    setNotice(`Reference ranges for "${editingTest.name}" updated successfully.`);
    setTimeout(() => setNotice(''), 3000);
  };

  return (
    <div>
      <h2 className="setup-page-title">Proofread & Reference Intervals</h2>

      {notice && (
        <div style={{ background: '#dcfce7', color: '#15803d', padding: '0.75rem', borderRadius: '6px', fontSize: '0.9rem', marginBottom: '1.25rem', border: '1px solid #86efac' }}>
          ✓ {notice}
        </div>
      )}

      {/* Category Pills */}
      <div style={{ display: 'flex', alignItems: 'center', gap: '0.75rem', marginBottom: '1rem', overflowX: 'auto', whiteSpace: 'nowrap', paddingBottom: '0.5rem' }}>
        <span style={{ fontWeight: '600', fontSize: '0.9rem', color: '#374151' }}>Select category:</span>
        {categories.map((cat) => (
          <button
            key={cat}
            onClick={() => setActiveCategory(cat)}
            style={{
              padding: '0.45rem 0.9rem',
              background: activeCategory === cat ? '#15803d' : '#f1f5f9',
              color: activeCategory === cat ? 'white' : '#475569',
              border: 'none',
              borderRadius: '20px',
              fontSize: '0.85rem',
              fontWeight: activeCategory === cat ? '600' : '500',
              cursor: 'pointer',
              transition: 'all 0.15s ease'
            }}
          >
            {cat}
          </button>
        ))}
      </div>

      <div style={{ background: '#fee2e2', color: '#b91c1c', padding: '0.75rem 1rem', borderRadius: '6px', fontSize: '0.85rem', marginBottom: '1.5rem', border: '1px solid #fca5a5' }}>
        ⚠️ <strong>IMPORTANT:</strong> Verify and calibrate laboratory normal values according to your machine reagent inserts and local population metrics.
      </div>

      <h3 style={{ fontSize: '1.15rem', marginBottom: '1rem', color: '#1e293b' }}>
        {activeCategory} Tests & Reference Ranges
      </h3>

      {/* Test list */}
      <div style={{ display: 'grid', gap: '1rem' }}>
        {currentTests.map((test) => (
          <div key={test.id} style={{ border: '1px solid #e2e8f0', borderRadius: '8px', padding: '1.25rem', background: '#ffffff', boxShadow: '0 1px 2px rgba(0,0,0,0.03)' }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '1rem' }}>
              <h4 style={{ margin: 0, fontSize: '1rem', color: '#0f172a', fontWeight: '600' }}>{test.name}</h4>
              <button
                onClick={() => setEditingTest(JSON.parse(JSON.stringify(test)))}
                className="lab-link-btn"
                style={{ fontSize: '0.85rem', color: '#15803d', display: 'flex', alignItems: 'center', gap: '0.25rem' }}
              >
                <PencilIcon className="lab-small-icon" style={{ width: '15px' }} /> Edit normal values
              </button>
            </div>

            <div style={{ paddingLeft: '1rem', borderLeft: '3px solid #10b981' }}>
              {test.ranges.map((r, idx) => (
                <div key={idx} style={{ marginBottom: idx === test.ranges.length - 1 ? 0 : '0.75rem' }}>
                  <div style={{ fontSize: '0.8rem', color: '#64748b', fontWeight: '600' }}>
                    {r.gender} ({r.age})
                  </div>
                  <div style={{ fontSize: '0.95rem', color: '#1e293b', fontWeight: '500' }}>
                    {r.val}
                  </div>
                </div>
              ))}
            </div>
          </div>
        ))}
      </div>

      {/* Edit Modal */}
      {editingTest && (
        <div style={{ position: 'fixed', inset: 0, background: 'rgba(0,0,0,0.5)', display: 'flex', alignItems: 'center', justifyContent: 'center', zIndex: 1000, padding: '1rem' }}>
          <div style={{ background: 'white', borderRadius: '8px', padding: '1.5rem', width: '100%', maxWidth: '520px', maxHeight: '90vh', overflowY: 'auto' }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '1rem', borderBottom: '1px solid #e2e8f0', paddingBottom: '0.75rem' }}>
              <h3 style={{ margin: 0, fontSize: '1.1rem', color: '#1e293b' }}>Edit Reference Values: {editingTest.name}</h3>
              <button onClick={() => setEditingTest(null)} style={{ border: 'none', background: 'none', cursor: 'pointer', color: '#64748b' }}>
                <XMarkIcon style={{ width: '20px' }} />
              </button>
            </div>

            <form onSubmit={handleSaveEdit}>
              {editingTest.ranges.map((range, index) => (
                <div key={index} style={{ marginBottom: '1rem', background: '#f8fafc', padding: '0.75rem', borderRadius: '6px' }}>
                  <div style={{ display: 'flex', gap: '0.5rem', marginBottom: '0.5rem' }}>
                    <div style={{ flex: 1 }}>
                      <label style={{ fontSize: '0.75rem', color: '#64748b', display: 'block' }}>Gender</label>
                      <input
                        type="text"
                        className="setup-input"
                        value={range.gender}
                        onChange={(e) => {
                          const updated = [...editingTest.ranges];
                          updated[index].gender = e.target.value;
                          setEditingTest({ ...editingTest, ranges: updated });
                        }}
                      />
                    </div>
                    <div style={{ flex: 1 }}>
                      <label style={{ fontSize: '0.75rem', color: '#64748b', display: 'block' }}>Age Bracket</label>
                      <input
                        type="text"
                        className="setup-input"
                        value={range.age}
                        onChange={(e) => {
                          const updated = [...editingTest.ranges];
                          updated[index].age = e.target.value;
                          setEditingTest({ ...editingTest, ranges: updated });
                        }}
                      />
                    </div>
                  </div>
                  <div>
                    <label style={{ fontSize: '0.75rem', color: '#64748b', display: 'block' }}>Normal Interval / Values</label>
                    <input
                      type="text"
                      className="setup-input"
                      value={range.val}
                      onChange={(e) => {
                        const updated = [...editingTest.ranges];
                        updated[index].val = e.target.value;
                        setEditingTest({ ...editingTest, ranges: updated });
                      }}
                      required
                    />
                  </div>
                </div>
              ))}

              <div style={{ display: 'flex', justifyContent: 'flex-end', gap: '0.75rem', marginTop: '1.25rem' }}>
                <button type="button" onClick={() => setEditingTest(null)} style={{ padding: '0.5rem 1rem', border: '1px solid #cbd5e1', borderRadius: '6px', background: 'white', cursor: 'pointer' }}>
                  Cancel
                </button>
                <button type="submit" className="setup-btn-blue">
                  Save Changes
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}

import React, { useState } from 'react';
import '../lab/LabShared.css';
import { PlusIcon, ArrowDownTrayIcon, PrinterIcon, XCircleIcon, PencilIcon, XMarkIcon } from '@heroicons/react/24/outline';
import useDemoResource from '../../hooks/useDemoResource';

export default function Ratelist() {
  const defaultRatelist = [
    { id: 1, name: 'ABG (Arterial Blood Gas)', modality: 'Lab', type: 'Tests', fee: 800, revShare: 150, gender: 'Both', active: true },
    { id: 2, name: 'ADA (Adenosine Deaminase)', modality: 'Lab', type: 'Tests', fee: 650, revShare: 100, gender: 'Both', active: true },
    { id: 3, name: 'AEC (Absolute Eosinophil Count)', modality: 'Lab', type: 'Tests', fee: 200, revShare: 30, gender: 'Both', active: true },
    { id: 4, name: 'AFB Stain (Acid Fast Bacilli)', modality: 'Lab', type: 'Tests', fee: 350, revShare: 50, gender: 'Both', active: true },
    { id: 5, name: 'AFP (Alpha Fetoprotein)', modality: 'Lab', type: 'Tests', fee: 900, revShare: 180, gender: 'Both', active: true },
    { id: 6, name: 'Complete Blood Count (CBC)', modality: 'Lab', type: 'Panels', fee: 350, revShare: 50, gender: 'Both', active: true },
    { id: 7, name: 'Lipid Profile', modality: 'Lab', type: 'Panels', fee: 650, revShare: 100, gender: 'Both', active: true },
    { id: 8, name: 'Liver Function Test (LFT)', modality: 'Lab', type: 'Panels', fee: 750, revShare: 120, gender: 'Both', active: true },
    { id: 9, name: 'Kidney Function Test (KFT)', modality: 'Lab', type: 'Panels', fee: 700, revShare: 110, gender: 'Both', active: true },
    { id: 10, name: 'Executive Health Checkup', modality: 'Lab', type: 'Packages', fee: 2499, revShare: 400, gender: 'Both', active: true },
    { id: 11, name: 'Abdomen USG', modality: 'USG', type: 'Tests', fee: 1200, revShare: 250, gender: 'Both', active: true },
    { id: 12, name: 'Pelvic USG', modality: 'USG', type: 'Tests', fee: 1100, revShare: 200, gender: 'Female', active: true },
    { id: 13, name: 'Chest PA Digital X-Ray', modality: 'Digital X-ray', type: 'Tests', fee: 500, revShare: 80, gender: 'Both', active: true },
    { id: 14, name: 'Knee Joint AP/LAT', modality: 'Digital X-ray', type: 'Tests', fee: 700, revShare: 120, gender: 'Both', active: true },
  ];

  const { data: ratelist, update: setRatelist } = useDemoResource('labsetu_setup_ratelist', defaultRatelist);

  const [activeModality, setActiveModality] = useState('Lab');
  const [activeType, setActiveType] = useState('Tests');
  const [bulkPercent, setBulkPercent] = useState('');
  const [isAddModalOpen, setIsAddModalOpen] = useState(false);
  const [newEntry, setNewEntry] = useState({ name: '', modality: 'Lab', type: 'Tests', fee: '', revShare: '', gender: 'Both' });
  const [notice, setNotice] = useState('');

  const modalities = ['Lab', 'USG', 'Digital X-ray', 'X-ray', 'Outsource Lab', 'ECG'];
  const types = ['Tests', 'Packages', 'Panels', 'Bill only'];

  const filteredItems = (ratelist || []).filter(item => {
    const matchesModality = activeModality === 'Lab' ? (item.modality === 'Lab' || !item.modality) : item.modality === activeModality;
    const matchesType = activeType ? item.type === activeType : true;
    return matchesModality && matchesType;
  });

  const handleBulkUpdate = () => {
    const pct = parseFloat(bulkPercent);
    if (isNaN(pct)) return;
    const updated = ratelist.map(item => {
      if (item.modality === activeModality) {
        const newRev = Math.round(Number(item.fee) * (pct / 100));
        return { ...item, revShare: newRev };
      }
      return item;
    });
    setRatelist(updated);
    setNotice(`Updated revenue share for ${activeModality} to ${pct}% across items.`);
    setBulkPercent('');
    setTimeout(() => setNotice(''), 3000);
  };

  const handleDownloadCsv = () => {
    const headers = ['ID,Name,Modality,Type,Fee,Revenue Share,Gender'];
    const rows = (ratelist || []).map(r => `"${r.id}","${r.name}","${r.modality}","${r.type}","${r.fee}","${r.revShare}","${r.gender}"`);
    const csvContent = 'data:text/csv;charset=utf-8,' + [headers, ...rows].join('\n');
    const encodedUri = encodeURI(csvContent);
    const link = document.createElement('a');
    link.setAttribute('href', encodedUri);
    link.setAttribute('download', `labsetu-ratelist-${new Date().toISOString().slice(0, 10)}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const handleRemove = (id) => {
    setRatelist(ratelist.filter(item => item.id !== id));
  };

  const handleFieldChange = (id, field, value) => {
    setRatelist(ratelist.map(item => item.id === id ? { ...item, [field]: value } : item));
  };

  const handleAddNew = (e) => {
    e.preventDefault();
    if (!newEntry.name.trim()) return;
    const created = {
      id: Date.now(),
      name: newEntry.name.trim(),
      modality: activeModality,
      type: newEntry.type || activeType,
      fee: Number(newEntry.fee) || 0,
      revShare: Number(newEntry.revShare) || 0,
      gender: newEntry.gender,
      active: true
    };
    setRatelist([...ratelist, created]);
    setIsAddModalOpen(false);
    setNewEntry({ name: '', modality: 'Lab', type: 'Tests', fee: '', revShare: '', gender: 'Both' });
    setNotice(`Test "${created.name}" added to ratelist.`);
    setTimeout(() => setNotice(''), 3000);
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', height: '100%' }}>
      {notice && (
        <div style={{ background: '#dcfce7', color: '#15803d', padding: '0.75rem', borderRadius: '6px', fontSize: '0.9rem', marginBottom: '1rem', border: '1px solid #86efac' }}>
          ✓ {notice}
        </div>
      )}

      {/* Top Filter Bar */}
      <div style={{ display: 'flex', gap: '1rem', alignItems: 'center', flexWrap: 'wrap', marginBottom: '1rem' }}>
        {/* Modality Pills */}
        <div style={{ display: 'flex', gap: '0.35rem', background: '#f8fafc', padding: '0.4rem', borderRadius: '8px', border: '1px solid #e2e8f0' }}>
          {modalities.map(m => (
            <button
              key={m}
              onClick={() => setActiveModality(m)}
              style={{
                padding: '0.45rem 0.85rem',
                background: activeModality === m ? '#15803d' : 'transparent',
                color: activeModality === m ? '#ffffff' : '#475569',
                border: 'none',
                borderRadius: '6px',
                fontWeight: activeModality === m ? '600' : '500',
                fontSize: '0.85rem',
                cursor: 'pointer'
              }}
            >
              {m}
            </button>
          ))}
        </div>

        {/* Bulk Update */}
        <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem', fontSize: '0.85rem', color: '#334155' }}>
          <span>Bulk rev share:</span>
          <input
            type="number"
            className="setup-input"
            style={{ width: '60px', padding: '0.3rem' }}
            placeholder="%"
            value={bulkPercent}
            onChange={(e) => setBulkPercent(e.target.value)}
          />
          <button
            onClick={handleBulkUpdate}
            className="setup-btn-blue"
            style={{ background: '#f1f5f9', color: '#334155', border: '1px solid #cbd5e1', padding: '0.35rem 0.75rem', fontSize: '0.85rem' }}
          >
            Apply to {activeModality}
          </button>
        </div>

        <div style={{ marginLeft: 'auto', display: 'flex', gap: '0.5rem' }}>
          <button
            onClick={handleDownloadCsv}
            className="setup-btn-blue"
            style={{ background: 'transparent', color: '#475569', border: '1px solid #cbd5e1', display: 'inline-flex', alignItems: 'center', gap: '0.35rem' }}
          >
            <ArrowDownTrayIcon style={{ width: '16px' }} /> Download CSV
          </button>
          <button
            onClick={() => setIsAddModalOpen(true)}
            className="setup-btn-blue"
            style={{ display: 'inline-flex', alignItems: 'center', gap: '0.35rem' }}
          >
            <PlusIcon style={{ width: '16px' }} /> Add New
          </button>
          <button
            onClick={() => window.print()}
            className="setup-btn-blue"
            style={{ background: 'transparent', color: '#475569', border: '1px solid #cbd5e1', display: 'inline-flex', alignItems: 'center', gap: '0.35rem' }}
          >
            <PrinterIcon style={{ width: '16px' }} /> Print
          </button>
        </div>
      </div>

      <div style={{ display: 'flex', gap: '1.5rem', marginBottom: '0.75rem', fontSize: '0.9rem' }}>
        <div style={{ fontWeight: '600', color: '#15803d', borderBottom: '2px solid #15803d', paddingBottom: '0.4rem' }}>
          Active <span style={{ background: '#dcfce7', color: '#15803d', padding: '0.15rem 0.5rem', borderRadius: '10px' }}>{filteredItems.length}</span>
        </div>
      </div>

      <div className="lab-tabs-row" style={{ marginBottom: '1rem' }}>
        <div className="lab-tabs" style={{ border: 'none', gap: '0.5rem' }}>
          {types.map(t => (
            <button
              key={t}
              onClick={() => setActiveType(t)}
              className={`lab-tab ${activeType === t ? 'active' : ''}`}
              style={{
                background: activeType === t ? '#f1f5f9' : '#ffffff',
                border: activeType === t ? '1px solid #cbd5e1' : '1px solid transparent',
                borderRadius: '20px',
                padding: '0.3rem 1rem'
              }}
            >
              {t}
            </button>
          ))}
        </div>
      </div>

      <table className="lab-data-table">
        <thead>
          <tr>
            <th>NAME</th>
            <th>MODALITY / TYPE</th>
            <th>FEE (₹)</th>
            <th>REVENUE SHARE (₹)</th>
            <th>GENDER</th>
            <th>ACTION</th>
          </tr>
        </thead>
        <tbody>
          {filteredItems.map((row) => (
            <tr key={row.id} className="lab-hover-interactive">
              <td style={{ fontWeight: '500' }}>
                {row.name}
              </td>
              <td style={{ fontSize: '0.85rem', color: '#64748b' }}>
                {row.modality} · {row.type}
              </td>
              <td>
                <input
                  type="number"
                  className="setup-input"
                  value={row.fee}
                  onChange={(e) => handleFieldChange(row.id, 'fee', Number(e.target.value))}
                  style={{ width: '90px', padding: '0.3rem' }}
                />
              </td>
              <td>
                <input
                  type="number"
                  className="setup-input"
                  value={row.revShare}
                  onChange={(e) => handleFieldChange(row.id, 'revShare', Number(e.target.value))}
                  style={{ width: '90px', padding: '0.3rem' }}
                />
              </td>
              <td>
                <select
                  className="setup-input"
                  value={row.gender}
                  onChange={(e) => handleFieldChange(row.id, 'gender', e.target.value)}
                  style={{ width: '100px', padding: '0.3rem' }}
                >
                  <option>Both</option>
                  <option>Male</option>
                  <option>Female</option>
                </select>
              </td>
              <td>
                <button
                  onClick={() => handleRemove(row.id)}
                  className="lab-link-btn"
                  style={{ color: '#ef4444', display: 'inline-flex', alignItems: 'center', gap: '0.25rem' }}
                >
                  <XCircleIcon style={{ width: '16px' }} /> Remove
                </button>
              </td>
            </tr>
          ))}
          {filteredItems.length === 0 && (
            <tr>
              <td colSpan="6" style={{ textAlign: 'center', padding: '2rem', color: '#64748b' }}>
                No items found for {activeModality} ({activeType}). Click "+ Add New" to add one.
              </td>
            </tr>
          )}
        </tbody>
      </table>

      {/* Add New Modal */}
      {isAddModalOpen && (
        <div style={{ position: 'fixed', inset: 0, background: 'rgba(0,0,0,0.5)', display: 'flex', alignItems: 'center', justifyContent: 'center', zIndex: 1000, padding: '1rem' }}>
          <div style={{ background: 'white', borderRadius: '8px', padding: '1.5rem', width: '100%', maxWidth: '480px' }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '1.25rem' }}>
              <h3 style={{ margin: 0, fontSize: '1.1rem', color: '#1e293b' }}>Add Ratelist Item ({activeModality})</h3>
              <button onClick={() => setIsAddModalOpen(false)} style={{ border: 'none', background: 'none', cursor: 'pointer', color: '#64748b' }}>
                <XMarkIcon style={{ width: '20px' }} />
              </button>
            </div>

            <form onSubmit={handleAddNew}>
              <div className="setup-form-group">
                <label className="setup-label">Investigation / Test Name</label>
                <input
                  type="text"
                  className="setup-input"
                  placeholder="e.g. Vitamin D Total, Renal Doppler"
                  value={newEntry.name}
                  onChange={(e) => setNewEntry({ ...newEntry, name: e.target.value })}
                  required
                />
              </div>

              <div style={{ display: 'flex', gap: '1rem', marginBottom: '1rem' }}>
                <div style={{ flex: 1 }}>
                  <label className="setup-label">Entry Type</label>
                  <select
                    className="setup-input"
                    value={newEntry.type}
                    onChange={(e) => setNewEntry({ ...newEntry, type: e.target.value })}
                  >
                    <option value="Tests">Test</option>
                    <option value="Packages">Package</option>
                    <option value="Panels">Panel</option>
                    <option value="Bill only">Bill only</option>
                  </select>
                </div>
                <div style={{ flex: 1 }}>
                  <label className="setup-label">Gender</label>
                  <select
                    className="setup-input"
                    value={newEntry.gender}
                    onChange={(e) => setNewEntry({ ...newEntry, gender: e.target.value })}
                  >
                    <option value="Both">Both</option>
                    <option value="Male">Male</option>
                    <option value="Female">Female</option>
                  </select>
                </div>
              </div>

              <div style={{ display: 'flex', gap: '1rem', marginBottom: '1.25rem' }}>
                <div style={{ flex: 1 }}>
                  <label className="setup-label">Fee (₹)</label>
                  <input
                    type="number"
                    className="setup-input"
                    placeholder="e.g. 500"
                    value={newEntry.fee}
                    onChange={(e) => setNewEntry({ ...newEntry, fee: e.target.value })}
                    required
                  />
                </div>
                <div style={{ flex: 1 }}>
                  <label className="setup-label">Revenue Share (₹)</label>
                  <input
                    type="number"
                    className="setup-input"
                    placeholder="e.g. 100"
                    value={newEntry.revShare}
                    onChange={(e) => setNewEntry({ ...newEntry, revShare: e.target.value })}
                  />
                </div>
              </div>

              <div style={{ display: 'flex', justifyContent: 'flex-end', gap: '0.75rem' }}>
                <button type="button" onClick={() => setIsAddModalOpen(false)} style={{ padding: '0.5rem 1rem', border: '1px solid #cbd5e1', borderRadius: '6px', background: 'white', cursor: 'pointer' }}>
                  Cancel
                </button>
                <button type="submit" className="setup-btn-blue">
                  Add Item
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}

