                  LabSetu Software
                </div>
              </div>
              <div className="phone-button"></div>
            </div>
          </div>

          {/* Phone 2 */}
          <div className="sms-phone-container">
            <label style={{ display: 'flex', alignItems: 'center', gap: '0.5rem', marginBottom: '1rem', fontWeight: '500', cursor: 'pointer' }}>
              <input
                type="checkbox"
