import React, { useState } from 'react';
import '../lab/LabShared.css';
import './TestPanels.css';
import { PlusIcon, QuestionMarkCircleIcon, ChevronDownIcon, ChevronUpIcon, ChevronUpDownIcon, PencilIcon, EyeIcon, XMarkIcon, TrashIcon } from '@heroicons/react/24/outline';
import useDemoResource from '../../hooks/useDemoResource';

export default function TestPanels() {
  const initialData = [
    {
      id: 1,
      order: 1,
      name: 'Complete Blood Count (CBC)',
      category: 'Haematology',
      tests: 'Hemoglobin, Total Leukocyte Count, Platelet Count, Differential Count, RBC Indices (14 tests)',
      ratelist: 'CBC with GBP, Complete Blood Count (CBC)'
    },
    {
      id: 2,
      order: 2,
      name: 'CBC (with absolute counts)',
      category: 'Haematology',
      tests: 'Hemoglobin, TLC, Absolute Neutrophil, Lymphocyte, Monocyte, Eosinophil Count (16 tests)',
      ratelist: 'Antenatal Package, Cardiac package'
    },
    {
      id: 3,
      order: 3,
      name: 'CBC with ESR',
      category: 'Haematology',
      tests: 'Hemoglobin, Total Leukocyte Count, ESR Westergren (15 tests)',
      ratelist: 'Anemia package, Arthritis Package'
    },
    {
      id: 4,
      order: 4,
      name: 'BT & CT',
      category: 'Haematology',
      tests: 'Bleeding Time, Clotting Time (2 tests)',
      ratelist: 'BT & CT Coagulation Profile'
    }
  ];

  const { data: panels, update: setPanels } = useDemoResource('labsetu_setup_panels', initialData);
  const [showReorderHelp, setShowReorderHelp] = useState(false);
  const [modalMode, setModalMode] = useState(null); // 'add' | 'edit' | 'view'
  const [selectedPanel, setSelectedPanel] = useState(null);
  const [panelForm, setPanelForm] = useState({ name: '', category: 'Haematology', tests: '', ratelist: '' });
  const [notice, setNotice] = useState('');

  const openAdd = () => {
    setPanelForm({ name: '', category: 'Haematology', tests: '', ratelist: '' });
    setModalMode('add');
  };

  const openEdit = (item) => {
    setSelectedPanel(item);
    setPanelForm({ ...item });
    setModalMode('edit');
  };

  const openView = (item) => {
    setSelectedPanel(item);
    setModalMode('view');
  };

  const handleSave = (e) => {
    e.preventDefault();
    if (!panelForm.name.trim()) return;

    if (modalMode === 'add') {
      const created = {
        id: Date.now(),
        order: (panels || []).length + 1,
        ...panelForm
      };
      setPanels([...(panels || []), created]);
      setNotice(`Test panel "${created.name}" created successfully.`);
    } else if (modalMode === 'edit') {
      setPanels((panels || []).map(p => p.id === selectedPanel.id ? { ...p, ...panelForm } : p));
      setNotice(`Test panel "${panelForm.name}" updated successfully.`);
    }
    setModalMode(null);
    setTimeout(() => setNotice(''), 3000);
  };

  const handleDelete = (id) => {
    setPanels((panels || []).filter(p => p.id !== id));
    setModalMode(null);
    setNotice('Test panel removed.');
    setTimeout(() => setNotice(''), 3000);
  };

  return (
    <div>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '1.5rem' }}>
        <h2 className="setup-page-title" style={{ marginBottom: 0 }}>Test Panels</h2>
        <button onClick={openAdd} className="setup-btn-blue" style={{ display: 'inline-flex', alignItems: 'center', gap: '0.35rem' }}>
          <PlusIcon className="setup-icon" style={{ width: '18px' }} /> Add new
        </button>
      </div>

      {notice && (
        <div style={{ background: '#dcfce7', color: '#15803d', padding: '0.75rem', borderRadius: '6px', fontSize: '0.9rem', marginBottom: '1rem', border: '1px solid #86efac' }}>
          ✓ {notice}
        </div>
      )}

      <div
        className="test-panels-help-block"
        onClick={() => setShowReorderHelp(!showReorderHelp)}
        style={{ cursor: 'pointer', userSelect: 'none' }}
      >
        <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
          <QuestionMarkCircleIcon style={{ width: '20px' }} />
          <span>How to reorder?</span>
        </div>
        {showReorderHelp ? <ChevronUpIcon style={{ width: '18px' }} /> : <ChevronDownIcon style={{ width: '18px' }} />}
      </div>

      {showReorderHelp && (
        <div style={{ background: '#f8fafc', border: '1px solid #e2e8f0', padding: '1rem', borderRadius: '6px', marginBottom: '1rem', fontSize: '0.85rem', color: '#475569' }}>
          Panels define groups of clinical test parameters that print together sequentially on reports. Reordering changes the sequence of tests appearing in doctor reports and printouts.
        </div>
      )}

      <table className="lab-data-table">
        <thead>
          <tr>
            <th>ORDER</th>
            <th>NAME</th>
            <th>CATEGORY</th>
            <th>TESTS</th>
            <th>RATELIST ENTRIES</th>
            <th>ACTION</th>
          </tr>
        </thead>
        <tbody>
          {(panels || []).map((row) => (
            <tr key={row.id || row.order} className="lab-hover-interactive">
              <td>
                <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem', color: '#6b7280' }}>
                  <ChevronUpDownIcon style={{ width: '16px' }} /> {row.order}.
                </div>
              </td>
              <td style={{ fontWeight: '500', color: '#0f172a' }}>{row.name}</td>
              <td>{row.category}</td>
              <td style={{ fontSize: '0.85rem', color: '#475569', maxWidth: '300px' }}>{row.tests}</td>
              <td style={{ fontSize: '0.85rem', color: '#64748b' }}>{row.ratelist}</td>
              <td>
                <div className="lab-actions-inline">
                  <button onClick={() => openEdit(row)} className="lab-link-btn" style={{ display: 'inline-flex', alignItems: 'center', gap: '0.25rem' }}>
                    <PencilIcon className="lab-small-icon" /> Edit
                  </button>
                  <button onClick={() => openView(row)} className="lab-link-btn" style={{ marginLeft: '0.5rem', display: 'inline-flex', alignItems: 'center', gap: '0.25rem' }}>
                    <EyeIcon className="lab-small-icon" /> View
                  </button>
                </div>
              </td>
            </tr>
          ))}
          {(panels || []).length === 0 && (
            <tr>
              <td colSpan="6" style={{ textAlign: 'center', padding: '2rem', color: '#64748b' }}>
                No test panels defined. Click "+ Add new" to create one.
              </td>
            </tr>
          )}
        </tbody>
      </table>

      {/* Modal: Add or Edit */}
      {(modalMode === 'add' || modalMode === 'edit') && (
        <div style={{ position: 'fixed', inset: 0, background: 'rgba(0,0,0,0.5)', display: 'flex', alignItems: 'center', justifyContent: 'center', zIndex: 1000, padding: '1rem' }}>
          <div style={{ background: 'white', borderRadius: '8px', padding: '1.5rem', width: '100%', maxWidth: '520px' }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '1.25rem' }}>
              <h3 style={{ margin: 0, fontSize: '1.1rem', color: '#1e293b' }}>
                {modalMode === 'add' ? 'Create New Test Panel' : `Edit Panel: ${selectedPanel?.name}`}
              </h3>
              <button onClick={() => setModalMode(null)} style={{ border: 'none', background: 'none', cursor: 'pointer', color: '#64748b' }}>
                <XMarkIcon style={{ width: '20px' }} />
              </button>
            </div>

            <form onSubmit={handleSave}>
              <div className="setup-form-group">
                <label className="setup-label">Panel Name</label>
                <input
                  type="text"
                  className="setup-input"
                  placeholder="e.g. Comprehensive Metabolic Panel (CMP)"
                  value={panelForm.name}
                  onChange={(e) => setPanelForm({ ...panelForm, name: e.target.value })}
                  required
                />
              </div>

              <div className="setup-form-group">
                <label className="setup-label">Category</label>
                <select
                  className="setup-input"
                  value={panelForm.category}
                  onChange={(e) => setPanelForm({ ...panelForm, category: e.target.value })}
                >
                  <option value="Haematology">Haematology</option>
                  <option value="Biochemistry">Biochemistry</option>
                  <option value="Serology & Immunology">Serology & Immunology</option>
                  <option value="Clinical Pathology">Clinical Pathology</option>
                  <option value="Microbiology">Microbiology</option>
                </select>
              </div>

              <div className="setup-form-group">
                <label className="setup-label">Included Test Parameters</label>
                <textarea
                  className="setup-input"
                  rows={3}
                  placeholder="List constituent tests separated by commas..."
                  value={panelForm.tests}
                  onChange={(e) => setPanelForm({ ...panelForm, tests: e.target.value })}
                  required
                />
              </div>

              <div className="setup-form-group">
                <label className="setup-label">Associated Ratelist Packages</label>
                <input
                  type="text"
                  className="setup-input"
                  placeholder="e.g. Master Health Package, Pre-Op Panel"
                  value={panelForm.ratelist}
                  onChange={(e) => setPanelForm({ ...panelForm, ratelist: e.target.value })}
                />
              </div>

              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginTop: '1.5rem' }}>
                {modalMode === 'edit' ? (
                  <button
                    type="button"
                    onClick={() => handleDelete(selectedPanel.id)}
                    style={{ color: '#ef4444', background: 'none', border: 'none', cursor: 'pointer', display: 'flex', alignItems: 'center', gap: '0.25rem', fontSize: '0.9rem' }}
                  >
                    <TrashIcon style={{ width: '16px' }} /> Delete Panel
                  </button>
                ) : <div />}

                <div style={{ display: 'flex', gap: '0.75rem' }}>
                  <button type="button" onClick={() => setModalMode(null)} style={{ padding: '0.5rem 1rem', border: '1px solid #cbd5e1', borderRadius: '6px', background: 'white', cursor: 'pointer' }}>
                    Cancel
                  </button>
                  <button type="submit" className="setup-btn-blue">
                    {modalMode === 'add' ? 'Create Panel' : 'Save Changes'}
                  </button>
                </div>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* Modal: View */}
      {modalMode === 'view' && selectedPanel && (
        <div style={{ position: 'fixed', inset: 0, background: 'rgba(0,0,0,0.5)', display: 'flex', alignItems: 'center', justifyContent: 'center', zIndex: 1000, padding: '1rem' }}>
          <div style={{ background: 'white', borderRadius: '8px', padding: '1.5rem', width: '100%', maxWidth: '520px' }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '1.25rem' }}>
              <h3 style={{ margin: 0, fontSize: '1.1rem', color: '#1e293b' }}>{selectedPanel.name}</h3>
              <button onClick={() => setModalMode(null)} style={{ border: 'none', background: 'none', cursor: 'pointer', color: '#64748b' }}>
                <XMarkIcon style={{ width: '20px' }} />
              </button>
            </div>

            <div style={{ marginBottom: '1rem', background: '#f8fafc', padding: '1rem', borderRadius: '6px' }}>
              <div style={{ fontSize: '0.85rem', color: '#64748b', marginBottom: '0.25rem' }}>Department Category:</div>
              <div style={{ fontWeight: '600', color: '#15803d', marginBottom: '0.75rem' }}>{selectedPanel.category}</div>

              <div style={{ fontSize: '0.85rem', color: '#64748b', marginBottom: '0.25rem' }}>Constituent Tests:</div>
              <div style={{ color: '#1e293b', marginBottom: '0.75rem', lineHeight: 1.5 }}>{selectedPanel.tests}</div>

              <div style={{ fontSize: '0.85rem', color: '#64748b', marginBottom: '0.25rem' }}>Linked Ratelist Packages:</div>
              <div style={{ color: '#334155' }}>{selectedPanel.ratelist || 'None linked'}</div>
            </div>

            <div style={{ display: 'flex', justifyContent: 'flex-end', gap: '0.75rem' }}>
              <button onClick={() => openEdit(selectedPanel)} className="setup-btn-blue">
                Edit Panel
              </button>
              <button onClick={() => setModalMode(null)} style={{ padding: '0.5rem 1rem', border: '1px solid #cbd5e1', borderRadius: '6px', background: 'white', cursor: 'pointer' }}>
                Close
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

import React, { useState } from 'react';
import '../lab/LabShared.css';
import { PlusIcon, PencilIcon, XMarkIcon, TrashIcon } from '@heroicons/react/24/outline';
import useDemoResource from '../../hooks/useDemoResource';

export default function ReportTemplatesUSG() {
  const defaultTemplates = [
    { id: 1, name: 'Normal Whole Abdomen', createdBy: 'Dr. John Smith', content: 'Liver: Normal in size and echogenicity. Gallbladder: Normal distension, no calculi. CBD: Normal caliber. Pancreas: Visualized portions unremarkable. Spleen: Normal size. Both Kidneys: Normal size, shape, position. No calculi or hydronephrosis. Urinary Bladder: Normal.' },
    { id: 2, name: 'Normal Female Pelvis', createdBy: 'Dr. Emily Davis', content: 'Uterus: Normal size, anteverted, uniform myometrial echotexture. Endometrial echo complex: Central and regular. Bilateral Ovaries: Normal size and appearance. No adnexal mass lesion or free fluid in pouch of Douglas.' },
    { id: 3, name: 'KUB & Prostate', createdBy: 'Dr. John Smith', content: 'Right and Left Kidneys: Normal bilateral size and parenchymal thickness. Urinary Bladder: Well filled with regular margins. Prostate: Normal size and homogenous echotexture, volume within limits.' }
  ];

  const { data: templates, update: setTemplates } = useDemoResource('labsetu_usg_templates', defaultTemplates);
  const [modalMode, setModalMode] = useState(null); // 'add' | 'edit'
  const [selectedTemplate, setSelectedTemplate] = useState(null);
  const [form, setForm] = useState({ name: '', createdBy: 'Dr. John Smith', content: '' });
  const [notice, setNotice] = useState('');

  const openAdd = () => {
    setForm({ name: '', createdBy: 'Dr. John Smith', content: '' });
    setModalMode('add');
  };

  const openEdit = (tpl) => {
    setSelectedTemplate(tpl);
    setForm({ ...tpl });
    setModalMode('edit');
  };

  const handleSave = (e) => {
    e.preventDefault();
    if (!form.name.trim()) return;

    if (modalMode === 'add') {
      const created = { id: Date.now(), ...form };
      setTemplates([...(templates || []), created]);
      setNotice(`Template "${created.name}" created.`);
    } else {
      setTemplates((templates || []).map(t => t.id === selectedTemplate.id ? { ...t, ...form } : t));
      setNotice(`Template "${form.name}" updated.`);
    }
    setModalMode(null);
    setTimeout(() => setNotice(''), 3000);
  };

  const handleDelete = (id) => {
    setTemplates((templates || []).filter(t => t.id !== id));
    setModalMode(null);
    setNotice('Template deleted.');
    setTimeout(() => setNotice(''), 3000);
  };

  return (
    <div className="lab-view-container">
      <div className="lab-header-row" style={{ justifyContent: 'space-between' }}>
        <h2>Report Templates (USG)</h2>
        <button onClick={openAdd} className="lab-btn lab-btn-blue" style={{ display: 'inline-flex', alignItems: 'center', gap: '0.35rem' }}>
          <PlusIcon className="lab-btn-icon" /> Add new template
        </button>
      </div>

      {notice && (
        <div style={{ background: '#dcfce7', color: '#15803d', padding: '0.75rem', borderRadius: '6px', fontSize: '0.9rem', marginBottom: '1rem', border: '1px solid #86efac' }}>
          ✓ {notice}
        </div>
      )}

      <table className="lab-data-table">
        <thead>
          <tr>
            <th>TEMPLATE NAME</th>
            <th>CREATED BY</th>
            <th>PREVIEW CONTENT</th>
            <th>ACTION</th>
          </tr>
        </thead>
        <tbody>
          {(templates || []).map(tpl => (
            <tr key={tpl.id} className="lab-hover-interactive">
              <td style={{ fontWeight: '500', color: '#0f172a' }}>{tpl.name}</td>
              <td style={{ color: '#475569' }}>{tpl.createdBy}</td>
              <td style={{ fontSize: '0.85rem', color: '#64748b', maxWidth: '380px' }}>
                {tpl.content.slice(0, 100)}...
              </td>
              <td>
                <button onClick={() => openEdit(tpl)} className="lab-link-btn" style={{ display: 'inline-flex', alignItems: 'center', gap: '0.25rem' }}>
                  <PencilIcon className="lab-small-icon" /> Edit
                </button>
              </td>
            </tr>
          ))}
          {(templates || []).length === 0 && (
            <tr>
              <td colSpan="4" style={{ textAlign: 'center', padding: '2rem', color: '#64748b' }}>
                No USG report templates found. Click "+ Add new template" to create one.
              </td>
            </tr>
          )}
        </tbody>
      </table>

      {/* Modal */}
      {modalMode && (
        <div style={{ position: 'fixed', inset: 0, background: 'rgba(0,0,0,0.5)', display: 'flex', alignItems: 'center', justifyContent: 'center', zIndex: 1000, padding: '1rem' }}>
          <div style={{ background: 'white', borderRadius: '8px', padding: '1.5rem', width: '100%', maxWidth: '520px' }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '1.25rem' }}>
              <h3 style={{ margin: 0, fontSize: '1.1rem' }}>
                {modalMode === 'add' ? 'Create USG Report Template' : 'Edit USG Report Template'}
              </h3>
              <button onClick={() => setModalMode(null)} style={{ border: 'none', background: 'none', cursor: 'pointer', color: '#64748b' }}>
                <XMarkIcon style={{ width: '20px' }} />
              </button>
            </div>

            <form onSubmit={handleSave}>
              <div className="setup-form-group">
                <label className="setup-label">Template Name</label>
                <input
                  type="text"
                  className="setup-input"
                  placeholder="e.g. Normal Obstetric Second Trimester"
                  value={form.name}
                  onChange={(e) => setForm({ ...form, name: e.target.value })}
                  required
                />
              </div>

              <div className="setup-form-group">
                <label className="setup-label">Created By (Radiologist)</label>
                <input
                  type="text"
                  className="setup-input"
                  value={form.createdBy}
                  onChange={(e) => setForm({ ...form, createdBy: e.target.value })}
                  required
                />
              </div>

              <div className="setup-form-group">
                <label className="setup-label">Standard Findings / Template Text</label>
                <textarea
                  className="setup-input"
                  rows={5}
                  placeholder="Enter boilerplate report findings..."
                  value={form.content}
                  onChange={(e) => setForm({ ...form, content: e.target.value })}
                  required
                />
              </div>

              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginTop: '1.25rem' }}>
                {modalMode === 'edit' ? (
                  <button
                    type="button"
                    onClick={() => handleDelete(selectedTemplate.id)}
                    style={{ color: '#ef4444', background: 'none', border: 'none', cursor: 'pointer', display: 'flex', alignItems: 'center', gap: '0.25rem', fontSize: '0.9rem' }}
                  >
                    <TrashIcon style={{ width: '16px' }} /> Delete
                  </button>
                ) : <div />}

                <div style={{ display: 'flex', gap: '0.75rem' }}>
                  <button type="button" onClick={() => setModalMode(null)} style={{ padding: '0.5rem 1rem', border: '1px solid #cbd5e1', borderRadius: '6px', background: 'white', cursor: 'pointer' }}>
                    Cancel
                  </button>
                  <button type="submit" className="setup-btn-blue">
                    {modalMode === 'add' ? 'Save Template' : 'Save Changes'}
                  </button>
                </div>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}

import React, { useState } from 'react';
import '../lab/LabShared.css';
import { PlusIcon, PencilIcon, XMarkIcon, TrashIcon } from '@heroicons/react/24/outline';
import useDemoResource from '../../hooks/useDemoResource';

export default function SignaturesUSG() {
  const defaultSignatures = [
    { id: 1, name: 'Dr. John Smith', designation: 'Chief Radiologist & Sonologist', regNo: 'MCI-48291', status: 'Active' },
    { id: 2, name: 'Dr. Emily Davis', designation: 'Consultant Radiologist', regNo: 'MCI-71829', status: 'Active' }
  ];

  const { data: signatures, update: setSignatures } = useDemoResource('labsetu_usg_signatures', defaultSignatures);
  const [modalMode, setModalMode] = useState(null); // 'add' | 'edit'
  const [selectedSig, setSelectedSig] = useState(null);
  const [form, setForm] = useState({ name: '', designation: '', regNo: '', status: 'Active' });
  const [notice, setNotice] = useState('');

  const openAdd = () => {
    setForm({ name: '', designation: '', regNo: '', status: 'Active' });
    setModalMode('add');
  };

  const openEdit = (sig) => {
    setSelectedSig(sig);
    setForm({ ...sig });
    setModalMode('edit');
  };

  const handleSave = (e) => {
    e.preventDefault();
    if (!form.name.trim()) return;

    if (modalMode === 'add') {
      const created = { id: Date.now(), ...form };
      setSignatures([...(signatures || []), created]);
      setNotice(`Signature authority "${created.name}" added.`);
    } else {
      setSignatures((signatures || []).map(s => s.id === selectedSig.id ? { ...s, ...form } : s));
      setNotice(`Signature for "${form.name}" updated.`);
    }
    setModalMode(null);
    setTimeout(() => setNotice(''), 3000);
  };

  const handleDelete = (id) => {
    setSignatures((signatures || []).filter(s => s.id !== id));
    setModalMode(null);
    setNotice('Signature profile removed.');
    setTimeout(() => setNotice(''), 3000);
  };

  return (
    <div className="lab-view-container">
      <div className="lab-header-row" style={{ justifyContent: 'space-between' }}>
        <h2>Signatures (USG)</h2>
        <button onClick={openAdd} className="lab-btn lab-btn-blue" style={{ display: 'inline-flex', alignItems: 'center', gap: '0.35rem' }}>
          <PlusIcon className="lab-btn-icon" /> Add new doctor
        </button>
      </div>

      {notice && (
        <div style={{ background: '#dcfce7', color: '#15803d', padding: '0.75rem', borderRadius: '6px', fontSize: '0.9rem', marginBottom: '1rem', border: '1px solid #86efac' }}>
          ✓ {notice}
        </div>
      )}

      <table className="lab-data-table">
        <thead>
          <tr>
            <th>DOCTOR NAME</th>
            <th>DESIGNATION</th>
            <th>REGISTRATION NO.</th>
            <th>STATUS</th>
            <th>ACTION</th>
          </tr>
        </thead>
        <tbody>
          {(signatures || []).map(sig => (
            <tr key={sig.id} className="lab-hover-interactive">
              <td style={{ fontWeight: '500', color: '#0f172a' }}>{sig.name}</td>
              <td>{sig.designation}</td>
              <td style={{ color: '#64748b' }}>{sig.regNo || '—'}</td>
              <td>
                <span style={{ background: '#dcfce7', color: '#15803d', padding: '0.2rem 0.5rem', borderRadius: '12px', fontSize: '0.8rem', fontWeight: '500' }}>
                  {sig.status}
                </span>
              </td>
              <td>
                <button onClick={() => openEdit(sig)} className="lab-link-btn" style={{ display: 'inline-flex', alignItems: 'center', gap: '0.25rem' }}>
                  <PencilIcon className="lab-small-icon" /> Edit
                </button>
              </td>
            </tr>
          ))}
          {(signatures || []).length === 0 && (
            <tr>
              <td colSpan="5" style={{ textAlign: 'center', padding: '2rem', color: '#64748b' }}>
                No radiologist signatures configured.
              </td>
            </tr>
          )}
        </tbody>
      </table>

      {/* Modal */}
      {modalMode && (
        <div style={{ position: 'fixed', inset: 0, background: 'rgba(0,0,0,0.5)', display: 'flex', alignItems: 'center', justifyContent: 'center', zIndex: 1000, padding: '1rem' }}>
          <div style={{ background: 'white', borderRadius: '8px', padding: '1.5rem', width: '100%', maxWidth: '480px' }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '1.25rem' }}>
              <h3 style={{ margin: 0, fontSize: '1.1rem' }}>
                {modalMode === 'add' ? 'Add Doctor Signature (USG)' : 'Edit Doctor Signature'}
              </h3>
              <button onClick={() => setModalMode(null)} style={{ border: 'none', background: 'none', cursor: 'pointer', color: '#64748b' }}>
                <XMarkIcon style={{ width: '20px' }} />
              </button>
            </div>

            <form onSubmit={handleSave}>
              <div className="setup-form-group">
                <label className="setup-label">Doctor Full Name & Degree</label>
                <input
                  type="text"
                  className="setup-input"
                  placeholder="e.g. Dr. Rajesh Verma, MD (Radiodiagnosis)"
                  value={form.name}
                  onChange={(e) => setForm({ ...form, name: e.target.value })}
                  required
                />
              </div>

              <div className="setup-form-group">
                <label className="setup-label">Clinical Designation</label>
                <input
                  type="text"
                  className="setup-input"
                  placeholder="e.g. Senior Consultant Sonologist"
                  value={form.designation}
                  onChange={(e) => setForm({ ...form, designation: e.target.value })}
                  required
                />
              </div>

              <div className="setup-form-group">
                <label className="setup-label">Medical Council Registration No.</label>
                <input
                  type="text"
                  className="setup-input"
                  placeholder="e.g. DMC/R/12495"
                  value={form.regNo}
                  onChange={(e) => setForm({ ...form, regNo: e.target.value })}
                  required
                />
              </div>

              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginTop: '1.25rem' }}>
                {modalMode === 'edit' ? (
                  <button
                    type="button"
                    onClick={() => handleDelete(selectedSig.id)}
                    style={{ color: '#ef4444', background: 'none', border: 'none', cursor: 'pointer', display: 'flex', alignItems: 'center', gap: '0.25rem', fontSize: '0.9rem' }}
                  >
                    <TrashIcon style={{ width: '16px' }} /> Delete
                  </button>
                ) : <div />}

                <div style={{ display: 'flex', gap: '0.75rem' }}>
                  <button type="button" onClick={() => setModalMode(null)} style={{ padding: '0.5rem 1rem', border: '1px solid #cbd5e1', borderRadius: '6px', background: 'white', cursor: 'pointer' }}>
                    Cancel
                  </button>
                  <button type="submit" className="setup-btn-blue">
                    Save Signature
                  </button>
                </div>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}

import React, { useState } from 'react';
import '../cases/OutsourceCases.css';
import { PlusIcon, EyeIcon, PrinterIcon, XMarkIcon, MagnifyingGlassIcon } from '@heroicons/react/24/outline';
import useDemoResource from '../../hooks/useDemoResource';

export default function TodaysCasesUSG() {
  const initialCases = [
    { id: 'U-101', date: '2026-10-17', patient: 'John Smith', age: '45/M', investigations: 'Abdomen USG', sonologist: 'Dr. John Smith', status: 'New', findings: 'Liver size 14.5 cm with normal echogenicity. Gallbladder well distended, no calculi. Pancreas, spleen, both kidneys normal.' },
    { id: 'U-102', date: '2026-10-17', patient: 'Alice Brown', age: '32/F', investigations: 'Pelvic USG', sonologist: 'Dr. Emily Davis', status: 'In Progress', findings: 'Anteverted normal sized uterus. Endometrial thickness 7.2 mm. Both ovaries show physiological follicles.' },
    { id: 'U-103', date: '2026-10-17', patient: 'Tom Hanks', age: '58/M', investigations: 'Renal USG & KUB', sonologist: 'Dr. John Smith', status: 'Completed', findings: 'Bilateral kidneys normal in size, shape and position with maintained corticomedullary differentiation. No hydronephrosis.' },
  ];

  const { data: cases, update: setCases } = useDemoResource('labsetu_usg_todays_cases', initialCases);
  const [searchTerm, setSearchTerm] = useState('');
  const [statusFilter, setStatusFilter] = useState('All');
  const [selectedCase, setSelectedCase] = useState(null);
  const [isAddModalOpen, setIsAddModalOpen] = useState(false);
  const [newCase, setNewCase] = useState({ patient: '', age: '', investigations: 'Abdomen USG', sonologist: 'Dr. John Smith' });
  const [notice, setNotice] = useState('');

  const filteredCases = (cases || []).filter(c => {
    const matchesSearch = c.patient.toLowerCase().includes(searchTerm.toLowerCase()) ||
                          c.id.toLowerCase().includes(searchTerm.toLowerCase()) ||
                          c.investigations.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesStatus = statusFilter === 'All' ? true : c.status === statusFilter;
    return matchesSearch && matchesStatus;
  });

  const handleStatusChange = (id, newStatus) => {
    const updated = (cases || []).map(c => c.id === id ? { ...c, status: newStatus } : c);
    setCases(updated);
    if (selectedCase && selectedCase.id === id) {
      setSelectedCase({ ...selectedCase, status: newStatus });
    }
  };

  const handleAddCase = (e) => {
    e.preventDefault();
    if (!newCase.patient.trim()) return;
    const created = {
      id: `U-${Math.floor(100 + Math.random() * 900)}`,
      date: new Date().toISOString().slice(0, 10),
      patient: newCase.patient.trim(),
      age: newCase.age.trim() || '30/M',
      investigations: newCase.investigations,
      sonologist: newCase.sonologist,
      status: 'New',
      findings: 'Ultrasound scan ordered. Preliminary scan pending sonologist review.'
    };
    setCases([created, ...(cases || [])]);
    setIsAddModalOpen(false);
    setNewCase({ patient: '', age: '', investigations: 'Abdomen USG', sonologist: 'Dr. John Smith' });
    setNotice(`Case ${created.id} registered for ${created.patient}.`);
    setTimeout(() => setNotice(''), 3000);
  };

  return (
    <div className="cases-container">
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '1.25rem', flexWrap: 'wrap', gap: '1rem' }}>
        <h2 style={{ margin: 0 }}>Today's cases (USG)</h2>
        <button
          onClick={() => setIsAddModalOpen(true)}
          style={{ padding: '0.5rem 1rem', background: '#15803d', color: 'white', border: 'none', borderRadius: '6px', cursor: 'pointer', display: 'inline-flex', alignItems: 'center', gap: '0.35rem', fontWeight: '500' }}
        >
          <PlusIcon style={{ width: '18px' }} /> Schedule USG Case
        </button>
      </div>

      {notice && (
        <div style={{ background: '#dcfce7', color: '#15803d', padding: '0.75rem', borderRadius: '6px', fontSize: '0.9rem', marginBottom: '1rem', border: '1px solid #86efac' }}>
          ✓ {notice}
        </div>
      )}

      {/* Filter Row */}
      <div className="cases-date-picker" style={{ display: 'flex', gap: '1rem', alignItems: 'center', flexWrap: 'wrap' }}>
        <div style={{ display: 'flex', alignItems: 'center', background: 'white', border: '1px solid #cbd5e1', borderRadius: '6px', padding: '0.4rem 0.75rem', width: '280px' }}>
          <MagnifyingGlassIcon style={{ width: '18px', color: '#64748b', marginRight: '0.5rem' }} />
          <input
            type="text"
            placeholder="Search patient, ID or scan..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            style={{ border: 'none', outline: 'none', width: '100%', fontSize: '0.9rem' }}
          />
        </div>

        <select
          value={statusFilter}
          onChange={(e) => setStatusFilter(e.target.value)}
          style={{ padding: '0.45rem 0.85rem', border: '1px solid #cbd5e1', borderRadius: '6px', background: 'white', fontSize: '0.9rem' }}
        >
          <option value="All">All Statuses</option>
          <option value="New">New</option>
          <option value="In Progress">In Progress</option>
          <option value="Completed">Completed</option>
        </select>
      </div>

      <table className="cases-table">
        <thead>
          <tr>
            <th>Reg. No.</th>
            <th>Date</th>
            <th>Patient</th>
            <th>Investigations</th>
            <th>Status</th>
            <th>Action</th>
          </tr>
        </thead>
        <tbody>
          {filteredCases.map((c) => (
            <tr key={c.id}>
              <td style={{ fontWeight: '600', color: '#15803d' }}>{c.id}</td>
              <td>{c.date}</td>
              <td>
                <div style={{ fontWeight: '500' }}>{c.patient}</div>
                <small style={{ color: '#64748b' }}>{c.age}</small>
              </td>
              <td>{c.investigations}</td>
              <td>
                <select
                  value={c.status}
                  onChange={(e) => handleStatusChange(c.id, e.target.value)}
                  style={{
                    padding: '0.2rem 0.5rem',
                    borderRadius: '4px',
                    border: '1px solid #cbd5e1',
                    fontSize: '0.85rem',
                    fontWeight: '600',
                    background: c.status === 'Completed' ? '#dcfce7' : c.status === 'In Progress' ? '#fef9c3' : '#fee2e2',
                    color: c.status === 'Completed' ? '#15803d' : c.status === 'In Progress' ? '#854d0e' : '#b91c1c'
                  }}
                >
                  <option value="New">New</option>
                  <option value="In Progress">In Progress</option>
                  <option value="Completed">Completed</option>
                </select>
              </td>
              <td>
                <button
                  onClick={() => setSelectedCase(c)}
                  style={{ background: 'none', border: 'none', color: '#15803d', cursor: 'pointer', display: 'inline-flex', alignItems: 'center', gap: '0.25rem', fontSize: '0.85rem', fontWeight: '500' }}
                >
                  <EyeIcon style={{ width: '16px' }} /> View Findings
                </button>
              </td>
            </tr>
          ))}
          {filteredCases.length === 0 && (
            <tr>
              <td colSpan="6" style={{ textAlign: 'center', padding: '2rem', color: '#64748b' }}>
                No USG cases match the filter criteria.
              </td>
            </tr>
          )}
        </tbody>
      </table>

      {/* Case Details Modal */}
      {selectedCase && (
        <div style={{ position: 'fixed', inset: 0, background: 'rgba(0,0,0,0.5)', display: 'flex', alignItems: 'center', justifyContent: 'center', zIndex: 1000, padding: '1rem' }}>
          <div style={{ background: 'white', borderRadius: '8px', padding: '1.5rem', width: '100%', maxWidth: '560px' }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '1rem', borderBottom: '1px solid #e2e8f0', paddingBottom: '0.75rem' }}>
              <div>
                <h3 style={{ margin: 0, fontSize: '1.15rem' }}>USG Case Record: {selectedCase.id}</h3>
                <small style={{ color: '#64748b' }}>{selectedCase.patient} ({selectedCase.age}) · {selectedCase.date}</small>
              </div>
              <button onClick={() => setSelectedCase(null)} style={{ border: 'none', background: 'none', cursor: 'pointer', color: '#64748b' }}>
                <XMarkIcon style={{ width: '20px' }} />
              </button>
            </div>

            <div style={{ background: '#f8fafc', padding: '1rem', borderRadius: '6px', marginBottom: '1rem' }}>
              <div style={{ marginBottom: '0.5rem' }}><strong>Investigation:</strong> {selectedCase.investigations}</div>
              <div style={{ marginBottom: '0.5rem' }}><strong>Sonologist:</strong> {selectedCase.sonologist}</div>
              <div style={{ marginBottom: '0.75rem' }}>
                <strong>Clinical Findings & Impression:</strong>
                <p style={{ marginTop: '0.25rem', color: '#334155', lineHeight: 1.5, background: 'white', padding: '0.75rem', borderRadius: '4px', border: '1px solid #e2e8f0' }}>
                  {selectedCase.findings}
                </p>
              </div>
              <div>
                <strong>Status:</strong> <span style={{ fontWeight: '600', color: selectedCase.status === 'Completed' ? '#15803d' : '#854d0e' }}>{selectedCase.status}</span>
              </div>
            </div>

            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
              <button
                onClick={() => window.print()}
                style={{ background: 'none', border: '1px solid #cbd5e1', padding: '0.5rem 1rem', borderRadius: '6px', cursor: 'pointer', display: 'flex', alignItems: 'center', gap: '0.35rem' }}
              >
                <PrinterIcon style={{ width: '16px' }} /> Print USG Report
              </button>
              <button
                onClick={() => setSelectedCase(null)}
                style={{ padding: '0.5rem 1rem', background: '#15803d', color: 'white', border: 'none', borderRadius: '6px', cursor: 'pointer' }}
              >
                Close
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Add Case Modal */}
      {isAddModalOpen && (
        <div style={{ position: 'fixed', inset: 0, background: 'rgba(0,0,0,0.5)', display: 'flex', alignItems: 'center', justifyContent: 'center', zIndex: 1000, padding: '1rem' }}>
          <div style={{ background: 'white', borderRadius: '8px', padding: '1.5rem', width: '100%', maxWidth: '480px' }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '1.25rem' }}>
              <h3 style={{ margin: 0, fontSize: '1.1rem' }}>Schedule USG Case</h3>
              <button onClick={() => setIsAddModalOpen(false)} style={{ border: 'none', background: 'none', cursor: 'pointer', color: '#64748b' }}>
                <XMarkIcon style={{ width: '20px' }} />
              </button>
            </div>

            <form onSubmit={handleAddCase}>
              <div className="setup-form-group">
                <label className="setup-label">Patient Name</label>
                <input
                  type="text"
                  className="setup-input"
                  placeholder="e.g. Ramesh Chandra"
                  value={newCase.patient}
                  onChange={(e) => setNewCase({ ...newCase, patient: e.target.value })}
                  required
                />
              </div>

              <div style={{ display: 'flex', gap: '1rem', marginBottom: '1rem' }}>
                <div style={{ flex: 1 }}>
                  <label className="setup-label">Age / Gender</label>
                  <input
                    type="text"
                    className="setup-input"
                    placeholder="e.g. 42/M"
                    value={newCase.age}
                    onChange={(e) => setNewCase({ ...newCase, age: e.target.value })}
                    required
                  />
                </div>
                <div style={{ flex: 1 }}>
                  <label className="setup-label">Sonologist</label>
                  <select
                    className="setup-input"
                    value={newCase.sonologist}
                    onChange={(e) => setNewCase({ ...newCase, sonologist: e.target.value })}
                  >
                    <option value="Dr. John Smith">Dr. John Smith</option>
                    <option value="Dr. Emily Davis">Dr. Emily Davis</option>
                  </select>
                </div>
              </div>

              <div className="setup-form-group">
                <label className="setup-label">Investigation / Scan Type</label>
                <select
                  className="setup-input"
                  value={newCase.investigations}
                  onChange={(e) => setNewCase({ ...newCase, investigations: e.target.value })}
                >
                  <option value="Abdomen USG">Abdomen USG</option>
                  <option value="Pelvic USG">Pelvic USG</option>
                  <option value="Renal USG & KUB">Renal USG & KUB</option>
                  <option value="Obstetric / Fetal USG">Obstetric / Fetal USG</option>
                  <option value="Thyroid USG">Thyroid USG</option>
                  <option value="Scrotal USG">Scrotal USG</option>
                </select>
              </div>

              <div style={{ display: 'flex', justifyContent: 'flex-end', gap: '0.75rem', marginTop: '1.25rem' }}>
                <button type="button" onClick={() => setIsAddModalOpen(false)} style={{ padding: '0.5rem 1rem', border: '1px solid #cbd5e1', borderRadius: '6px', background: 'white', cursor: 'pointer' }}>
                  Cancel
                </button>
                <button type="submit" style={{ padding: '0.5rem 1rem', background: '#15803d', color: 'white', border: 'none', borderRadius: '6px', cursor: 'pointer' }}>
                  Schedule Case
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}

import React, { useState } from 'react';
import '../lab/LabShared.css';
import { PlusIcon, PencilIcon, XMarkIcon, TrashIcon } from '@heroicons/react/24/outline';
import useDemoResource from '../../hooks/useDemoResource';

export default function ReportTemplatesXray() {
  const defaultTemplates = [
    { id: 1, name: 'Normal Chest PA View', createdBy: 'Dr. John Smith', content: 'Lungs: Clear bilaterally, no focal infiltrates, effusion or pneumothorax. Heart: Normal size, contour and cardiothoracic ratio. Mediastinum: Unremarkable, trachea central. Bones: Ribs, clavicles, visualized vertebrae normal. Diaphragm: Both domes and CP angles normal.' },
    { id: 2, name: 'Normal Knee Joint AP/LAT', createdBy: 'Dr. Emily Davis', content: 'Tibiofemoral and patellofemoral joint compartments show normal space. No osteophytes, subchondral cyst, or sclerosis. Visualized soft tissue structures unremarkable.' },
    { id: 3, name: 'Lumbosacral Spine AP/LAT', createdBy: 'Dr. John Smith', content: 'Lumbar lordosis preserved. Normal vertebral alignment without spondylolisthesis. Intervertebral disc spaces maintained. Pedicles and transverse processes intact.' }
  ];

  const { data: templates, update: setTemplates } = useDemoResource('labsetu_xray_templates', defaultTemplates);
  const [modalMode, setModalMode] = useState(null); // 'add' | 'edit'
  const [selectedTemplate, setSelectedTemplate] = useState(null);
  const [form, setForm] = useState({ name: '', createdBy: 'Dr. John Smith', content: '' });
  const [notice, setNotice] = useState('');

  const openAdd = () => {
    setForm({ name: '', createdBy: 'Dr. John Smith', content: '' });
    setModalMode('add');
  };

  const openEdit = (tpl) => {
    setSelectedTemplate(tpl);
    setForm({ ...tpl });
    setModalMode('edit');
  };

  const handleSave = (e) => {
    e.preventDefault();
    if (!form.name.trim()) return;

    if (modalMode === 'add') {
      const created = { id: Date.now(), ...form };
      setTemplates([...(templates || []), created]);
      setNotice(`Template "${created.name}" created.`);
    } else {
      setTemplates((templates || []).map(t => t.id === selectedTemplate.id ? { ...t, ...form } : t));
      setNotice(`Template "${form.name}" updated.`);
    }
    setModalMode(null);
    setTimeout(() => setNotice(''), 3000);
  };

  const handleDelete = (id) => {
    setTemplates((templates || []).filter(t => t.id !== id));
    setModalMode(null);
    setNotice('Template deleted.');
    setTimeout(() => setNotice(''), 3000);
  };

  return (
    <div className="lab-view-container">
      <div className="lab-header-row" style={{ justifyContent: 'space-between' }}>
        <h2>Report Templates (Digital X-Ray)</h2>
        <button onClick={openAdd} className="lab-btn lab-btn-blue" style={{ display: 'inline-flex', alignItems: 'center', gap: '0.35rem' }}>
          <PlusIcon className="lab-btn-icon" /> Add new template
        </button>
      </div>

      {notice && (
        <div style={{ background: '#dcfce7', color: '#15803d', padding: '0.75rem', borderRadius: '6px', fontSize: '0.9rem', marginBottom: '1rem', border: '1px solid #86efac' }}>
          ✓ {notice}
        </div>
      )}

      <table className="lab-data-table">
        <thead>
          <tr>
            <th>TEMPLATE NAME</th>
            <th>CREATED BY</th>
            <th>PREVIEW CONTENT</th>
            <th>ACTION</th>
          </tr>
        </thead>
        <tbody>
          {(templates || []).map(tpl => (
            <tr key={tpl.id} className="lab-hover-interactive">
              <td style={{ fontWeight: '500', color: '#0f172a' }}>{tpl.name}</td>
              <td style={{ color: '#475569' }}>{tpl.createdBy}</td>
              <td style={{ fontSize: '0.85rem', color: '#64748b', maxWidth: '380px' }}>
                {tpl.content.slice(0, 100)}...
              </td>
              <td>
                <button onClick={() => openEdit(tpl)} className="lab-link-btn" style={{ display: 'inline-flex', alignItems: 'center', gap: '0.25rem' }}>
                  <PencilIcon className="lab-small-icon" /> Edit
                </button>
              </td>
            </tr>
          ))}
          {(templates || []).length === 0 && (
            <tr>
              <td colSpan="4" style={{ textAlign: 'center', padding: '2rem', color: '#64748b' }}>
                No X-Ray report templates found. Click "+ Add new template" to create one.
              </td>
            </tr>
          )}
        </tbody>
      </table>

      {/* Modal */}
      {modalMode && (
        <div style={{ position: 'fixed', inset: 0, background: 'rgba(0,0,0,0.5)', display: 'flex', alignItems: 'center', justifyContent: 'center', zIndex: 1000, padding: '1rem' }}>
          <div style={{ background: 'white', borderRadius: '8px', padding: '1.5rem', width: '100%', maxWidth: '520px' }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '1.25rem' }}>
              <h3 style={{ margin: 0, fontSize: '1.1rem' }}>
                {modalMode === 'add' ? 'Create X-Ray Report Template' : 'Edit X-Ray Report Template'}
              </h3>
              <button onClick={() => setModalMode(null)} style={{ border: 'none', background: 'none', cursor: 'pointer', color: '#64748b' }}>
                <XMarkIcon style={{ width: '20px' }} />
              </button>
            </div>

            <form onSubmit={handleSave}>
              <div className="setup-form-group">
                <label className="setup-label">Template Name</label>
                <input
                  type="text"
                  className="setup-input"
                  placeholder="e.g. Normal Cervical Spine AP/LAT"
                  value={form.name}
                  onChange={(e) => setForm({ ...form, name: e.target.value })}
                  required
                />
              </div>

              <div className="setup-form-group">
                <label className="setup-label">Created By (Radiologist)</label>
                <input
                  type="text"
                  className="setup-input"
                  value={form.createdBy}
                  onChange={(e) => setForm({ ...form, createdBy: e.target.value })}
                  required
                />
              </div>

              <div className="setup-form-group">
                <label className="setup-label">Standard Findings / Template Text</label>
                <textarea
                  className="setup-input"
                  rows={5}
                  placeholder="Enter boilerplate findings..."
                  value={form.content}
                  onChange={(e) => setForm({ ...form, content: e.target.value })}
                  required
                />
              </div>

              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginTop: '1.25rem' }}>
                {modalMode === 'edit' ? (
                  <button
                    type="button"
                    onClick={() => handleDelete(selectedTemplate.id)}
                    style={{ color: '#ef4444', background: 'none', border: 'none', cursor: 'pointer', display: 'flex', alignItems: 'center', gap: '0.25rem', fontSize: '0.9rem' }}
                  >
                    <TrashIcon style={{ width: '16px' }} /> Delete
                  </button>
                ) : <div />}

                <div style={{ display: 'flex', gap: '0.75rem' }}>
                  <button type="button" onClick={() => setModalMode(null)} style={{ padding: '0.5rem 1rem', border: '1px solid #cbd5e1', borderRadius: '6px', background: 'white', cursor: 'pointer' }}>
                    Cancel
                  </button>
                  <button type="submit" className="setup-btn-blue">
                    {modalMode === 'add' ? 'Save Template' : 'Save Changes'}
                  </button>
                </div>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}

import React, { useState } from 'react';
import '../lab/LabShared.css';
import { PlusIcon, PencilIcon, XMarkIcon, TrashIcon } from '@heroicons/react/24/outline';
import useDemoResource from '../../hooks/useDemoResource';

export default function SignaturesXray() {
  const defaultSignatures = [
    { id: 1, name: 'Dr. John Smith', designation: 'Chief Radiologist & Medical Director', regNo: 'MCI-48291', status: 'Active' },
    { id: 2, name: 'Dr. Emily Davis', designation: 'Consultant Radiologist', regNo: 'MCI-71829', status: 'Active' }
  ];

  const { data: signatures, update: setSignatures } = useDemoResource('labsetu_xray_signatures', defaultSignatures);
  const [modalMode, setModalMode] = useState(null); // 'add' | 'edit'
  const [selectedSig, setSelectedSig] = useState(null);
  const [form, setForm] = useState({ name: '', designation: '', regNo: '', status: 'Active' });
  const [notice, setNotice] = useState('');

  const openAdd = () => {
    setForm({ name: '', designation: '', regNo: '', status: 'Active' });
    setModalMode('add');
  };

  const openEdit = (sig) => {
    setSelectedSig(sig);
    setForm({ ...sig });
    setModalMode('edit');
  };

  const handleSave = (e) => {
    e.preventDefault();
    if (!form.name.trim()) return;

    if (modalMode === 'add') {
      const created = { id: Date.now(), ...form };
      setSignatures([...(signatures || []), created]);
      setNotice(`Signature authority "${created.name}" added.`);
    } else {
      setSignatures((signatures || []).map(s => s.id === selectedSig.id ? { ...s, ...form } : s));
      setNotice(`Signature for "${form.name}" updated.`);
    }
    setModalMode(null);
    setTimeout(() => setNotice(''), 3000);
  };

  const handleDelete = (id) => {
    setSignatures((signatures || []).filter(s => s.id !== id));
    setModalMode(null);
    setNotice('Signature profile removed.');
    setTimeout(() => setNotice(''), 3000);
  };

  return (
    <div className="lab-view-container">
      <div className="lab-header-row" style={{ justifyContent: 'space-between' }}>
        <h2>Signatures (Digital X-Ray)</h2>
        <button onClick={openAdd} className="lab-btn lab-btn-blue" style={{ display: 'inline-flex', alignItems: 'center', gap: '0.35rem' }}>
          <PlusIcon className="lab-btn-icon" /> Add new doctor
        </button>
      </div>

      {notice && (
        <div style={{ background: '#dcfce7', color: '#15803d', padding: '0.75rem', borderRadius: '6px', fontSize: '0.9rem', marginBottom: '1rem', border: '1px solid #86efac' }}>
          ✓ {notice}
        </div>
      )}

      <table className="lab-data-table">
        <thead>
          <tr>
            <th>DOCTOR NAME</th>
            <th>DESIGNATION</th>
            <th>REGISTRATION NO.</th>
            <th>STATUS</th>
            <th>ACTION</th>
          </tr>
        </thead>
        <tbody>
          {(signatures || []).map(sig => (
            <tr key={sig.id} className="lab-hover-interactive">
              <td style={{ fontWeight: '500', color: '#0f172a' }}>{sig.name}</td>
              <td>{sig.designation}</td>
              <td style={{ color: '#64748b' }}>{sig.regNo || '—'}</td>
              <td>
                <span style={{ background: '#dcfce7', color: '#15803d', padding: '0.2rem 0.5rem', borderRadius: '12px', fontSize: '0.8rem', fontWeight: '500' }}>
                  {sig.status}
                </span>
              </td>
              <td>
                <button onClick={() => openEdit(sig)} className="lab-link-btn" style={{ display: 'inline-flex', alignItems: 'center', gap: '0.25rem' }}>
                  <PencilIcon className="lab-small-icon" /> Edit
                </button>
              </td>
            </tr>
          ))}
          {(signatures || []).length === 0 && (
            <tr>
              <td colSpan="5" style={{ textAlign: 'center', padding: '2rem', color: '#64748b' }}>
                No radiologist signatures configured.
              </td>
            </tr>
          )}
        </tbody>
      </table>

      {/* Modal */}
      {modalMode && (
        <div style={{ position: 'fixed', inset: 0, background: 'rgba(0,0,0,0.5)', display: 'flex', alignItems: 'center', justifyContent: 'center', zIndex: 1000, padding: '1rem' }}>
          <div style={{ background: 'white', borderRadius: '8px', padding: '1.5rem', width: '100%', maxWidth: '480px' }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '1.25rem' }}>
              <h3 style={{ margin: 0, fontSize: '1.1rem' }}>
                {modalMode === 'add' ? 'Add Doctor Signature (X-Ray)' : 'Edit Doctor Signature'}
              </h3>
              <button onClick={() => setModalMode(null)} style={{ border: 'none', background: 'none', cursor: 'pointer', color: '#64748b' }}>
                <XMarkIcon style={{ width: '20px' }} />
              </button>
            </div>

            <form onSubmit={handleSave}>
              <div className="setup-form-group">
                <label className="setup-label">Doctor Full Name & Qualifications</label>
                <input
                  type="text"
                  className="setup-input"
                  placeholder="e.g. Dr. Rajesh Verma, MD (Radiology)"
                  value={form.name}
                  onChange={(e) => setForm({ ...form, name: e.target.value })}
                  required
                />
              </div>

              <div className="setup-form-group">
                <label className="setup-label">Clinical Designation</label>
                <input
                  type="text"
                  className="setup-input"
                  placeholder="e.g. Consultant Radiologist"
                  value={form.designation}
                  onChange={(e) => setForm({ ...form, designation: e.target.value })}
                  required
                />
              </div>

              <div className="setup-form-group">
                <label className="setup-label">Medical Council Registration No.</label>
                <input
                  type="text"
                  className="setup-input"
                  placeholder="e.g. DMC/R/12495"
                  value={form.regNo}
                  onChange={(e) => setForm({ ...form, regNo: e.target.value })}
                  required
                />
              </div>

              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginTop: '1.25rem' }}>
                {modalMode === 'edit' ? (
                  <button
                    type="button"
                    onClick={() => handleDelete(selectedSig.id)}
                    style={{ color: '#ef4444', background: 'none', border: 'none', cursor: 'pointer', display: 'flex', alignItems: 'center', gap: '0.25rem', fontSize: '0.9rem' }}
                  >
                    <TrashIcon style={{ width: '16px' }} /> Delete
                  </button>
                ) : <div />}

                <div style={{ display: 'flex', gap: '0.75rem' }}>
                  <button type="button" onClick={() => setModalMode(null)} style={{ padding: '0.5rem 1rem', border: '1px solid #cbd5e1', borderRadius: '6px', background: 'white', cursor: 'pointer' }}>
                    Cancel
                  </button>
                  <button type="submit" className="setup-btn-blue">
                    Save Signature
                  </button>
                </div>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}

import React, { useState } from 'react';
import '../cases/OutsourceCases.css';
import { PlusIcon, EyeIcon, PrinterIcon, XMarkIcon, MagnifyingGlassIcon } from '@heroicons/react/24/outline';
import useDemoResource from '../../hooks/useDemoResource';

export default function TodaysCasesXray() {
  const initialCases = [
    { id: 'X-101', date: '2026-10-17', patient: 'John Smith', age: '45/M', investigations: 'Chest PA Digital X-Ray', radiologist: 'Dr. John Smith', status: 'New', findings: 'Bilateral lung fields clear. Trachea midline. Cardiac silhouette within normal limits. Costophrenic and cardiophrenic angles normal. Visualized bony thorax intact.' },
    { id: 'X-102', date: '2026-10-17', patient: 'Alice Brown', age: '32/F', investigations: 'Knee AP/LAT', radiologist: 'Dr. Emily Davis', status: 'In Progress', findings: 'Joint spaces maintained. No osteophytes or subchondral sclerosis. Visualized patella and soft tissue shadows unremarkable.' },
    { id: 'X-103', date: '2026-10-17', patient: 'Tom Hanks', age: '58/M', investigations: 'L-Spine AP/LAT', radiologist: 'Dr. John Smith', status: 'Completed', findings: 'Mild degenerative changes with anterior osteophytes at L4-L5 level. Intervertebral disc heights reasonably maintained.' },
  ];

  const { data: cases, update: setCases } = useDemoResource('labsetu_xray_todays_cases', initialCases);
  const [searchTerm, setSearchTerm] = useState('');
  const [statusFilter, setStatusFilter] = useState('All');
  const [selectedCase, setSelectedCase] = useState(null);
  const [isAddModalOpen, setIsAddModalOpen] = useState(false);
  const [newCase, setNewCase] = useState({ patient: '', age: '', investigations: 'Chest PA Digital X-Ray', radiologist: 'Dr. John Smith' });
  const [notice, setNotice] = useState('');

  const filteredCases = (cases || []).filter(c => {
    const matchesSearch = c.patient.toLowerCase().includes(searchTerm.toLowerCase()) ||
                          c.id.toLowerCase().includes(searchTerm.toLowerCase()) ||
                          c.investigations.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesStatus = statusFilter === 'All' ? true : c.status === statusFilter;
    return matchesSearch && matchesStatus;
  });

  const handleStatusChange = (id, newStatus) => {
    const updated = (cases || []).map(c => c.id === id ? { ...c, status: newStatus } : c);
    setCases(updated);
    if (selectedCase && selectedCase.id === id) {
      setSelectedCase({ ...selectedCase, status: newStatus });
    }
  };

  const handleAddCase = (e) => {
    e.preventDefault();
    if (!newCase.patient.trim()) return;
    const created = {
      id: `X-${Math.floor(100 + Math.random() * 900)}`,
      date: new Date().toISOString().slice(0, 10),
      patient: newCase.patient.trim(),
      age: newCase.age.trim() || '35/M',
      investigations: newCase.investigations,
      radiologist: newCase.radiologist,
      status: 'New',
      findings: 'X-ray exposure completed. Awaiting final radiological reading and impression sign-off.'
    };
    setCases([created, ...(cases || [])]);
    setIsAddModalOpen(false);
    setNewCase({ patient: '', age: '', investigations: 'Chest PA Digital X-Ray', radiologist: 'Dr. John Smith' });
    setNotice(`X-Ray case ${created.id} registered for ${created.patient}.`);
    setTimeout(() => setNotice(''), 3000);
  };

  return (
    <div className="cases-container">
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '1.25rem', flexWrap: 'wrap', gap: '1rem' }}>
        <h2 style={{ margin: 0 }}>Today's cases (Digital X-Ray)</h2>
        <button
          onClick={() => setIsAddModalOpen(true)}
          style={{ padding: '0.5rem 1rem', background: '#15803d', color: 'white', border: 'none', borderRadius: '6px', cursor: 'pointer', display: 'inline-flex', alignItems: 'center', gap: '0.35rem', fontWeight: '500' }}
        >
          <PlusIcon style={{ width: '18px' }} /> Schedule X-Ray
        </button>
      </div>

      {notice && (
        <div style={{ background: '#dcfce7', color: '#15803d', padding: '0.75rem', borderRadius: '6px', fontSize: '0.9rem', marginBottom: '1rem', border: '1px solid #86efac' }}>
          ✓ {notice}
        </div>
      )}

      {/* Filter Row */}
      <div className="cases-date-picker" style={{ display: 'flex', gap: '1rem', alignItems: 'center', flexWrap: 'wrap' }}>
        <div style={{ display: 'flex', alignItems: 'center', background: 'white', border: '1px solid #cbd5e1', borderRadius: '6px', padding: '0.4rem 0.75rem', width: '280px' }}>
          <MagnifyingGlassIcon style={{ width: '18px', color: '#64748b', marginRight: '0.5rem' }} />
          <input
            type="text"
            placeholder="Search patient, ID or view..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            style={{ border: 'none', outline: 'none', width: '100%', fontSize: '0.9rem' }}
          />
        </div>

        <select
          value={statusFilter}
          onChange={(e) => setStatusFilter(e.target.value)}
          style={{ padding: '0.45rem 0.85rem', border: '1px solid #cbd5e1', borderRadius: '6px', background: 'white', fontSize: '0.9rem' }}
        >
          <option value="All">All Statuses</option>
          <option value="New">New</option>
          <option value="In Progress">In Progress</option>
          <option value="Completed">Completed</option>
        </select>
      </div>

      <table className="cases-table">
        <thead>
          <tr>
            <th>Reg. No.</th>
            <th>Date</th>
            <th>Patient</th>
            <th>Investigations</th>
            <th>Status</th>
            <th>Action</th>
          </tr>
        </thead>
        <tbody>
          {filteredCases.map((c) => (
            <tr key={c.id}>
              <td style={{ fontWeight: '600', color: '#15803d' }}>{c.id}</td>
              <td>{c.date}</td>
              <td>
                <div style={{ fontWeight: '500' }}>{c.patient}</div>
                <small style={{ color: '#64748b' }}>{c.age}</small>
              </td>
              <td>{c.investigations}</td>
              <td>
                <select
                  value={c.status}
                  onChange={(e) => handleStatusChange(c.id, e.target.value)}
                  style={{
                    padding: '0.2rem 0.5rem',
                    borderRadius: '4px',
                    border: '1px solid #cbd5e1',
                    fontSize: '0.85rem',
                    fontWeight: '600',
                    background: c.status === 'Completed' ? '#dcfce7' : c.status === 'In Progress' ? '#fef9c3' : '#fee2e2',
                    color: c.status === 'Completed' ? '#15803d' : c.status === 'In Progress' ? '#854d0e' : '#b91c1c'
                  }}
                >
                  <option value="New">New</option>
                  <option value="In Progress">In Progress</option>
                  <option value="Completed">Completed</option>
                </select>
              </td>
              <td>
                <button
                  onClick={() => setSelectedCase(c)}
                  style={{ background: 'none', border: 'none', color: '#15803d', cursor: 'pointer', display: 'inline-flex', alignItems: 'center', gap: '0.25rem', fontSize: '0.85rem', fontWeight: '500' }}
                >
                  <EyeIcon style={{ width: '16px' }} /> View Report
                </button>
              </td>
            </tr>
          ))}
          {filteredCases.length === 0 && (
            <tr>
              <td colSpan="6" style={{ textAlign: 'center', padding: '2rem', color: '#64748b' }}>
                No X-Ray cases found.
              </td>
            </tr>
          )}
        </tbody>
      </table>

      {/* Case Details Modal */}
      {selectedCase && (
        <div style={{ position: 'fixed', inset: 0, background: 'rgba(0,0,0,0.5)', display: 'flex', alignItems: 'center', justifyContent: 'center', zIndex: 1000, padding: '1rem' }}>
          <div style={{ background: 'white', borderRadius: '8px', padding: '1.5rem', width: '100%', maxWidth: '560px' }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '1rem', borderBottom: '1px solid #e2e8f0', paddingBottom: '0.75rem' }}>
              <div>
                <h3 style={{ margin: 0, fontSize: '1.15rem' }}>X-Ray Report: {selectedCase.id}</h3>
                <small style={{ color: '#64748b' }}>{selectedCase.patient} ({selectedCase.age}) · {selectedCase.date}</small>
              </div>
              <button onClick={() => setSelectedCase(null)} style={{ border: 'none', background: 'none', cursor: 'pointer', color: '#64748b' }}>
                <XMarkIcon style={{ width: '20px' }} />
              </button>
            </div>

            <div style={{ background: '#f8fafc', padding: '1rem', borderRadius: '6px', marginBottom: '1rem' }}>
              <div style={{ marginBottom: '0.5rem' }}><strong>Investigation:</strong> {selectedCase.investigations}</div>
              <div style={{ marginBottom: '0.5rem' }}><strong>Radiologist:</strong> {selectedCase.radiologist}</div>
              <div style={{ marginBottom: '0.75rem' }}>
                <strong>Radiological Findings:</strong>
                <p style={{ marginTop: '0.25rem', color: '#334155', lineHeight: 1.5, background: 'white', padding: '0.75rem', borderRadius: '4px', border: '1px solid #e2e8f0' }}>
                  {selectedCase.findings}
                </p>
              </div>
              <div>
                <strong>Status:</strong> <span style={{ fontWeight: '600', color: selectedCase.status === 'Completed' ? '#15803d' : '#854d0e' }}>{selectedCase.status}</span>
              </div>
            </div>

            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
              <button
                onClick={() => window.print()}
                style={{ background: 'none', border: '1px solid #cbd5e1', padding: '0.5rem 1rem', borderRadius: '6px', cursor: 'pointer', display: 'flex', alignItems: 'center', gap: '0.35rem' }}
              >
                <PrinterIcon style={{ width: '16px' }} /> Print X-Ray Report
              </button>
              <button
                onClick={() => setSelectedCase(null)}
                style={{ padding: '0.5rem 1rem', background: '#15803d', color: 'white', border: 'none', borderRadius: '6px', cursor: 'pointer' }}
              >
                Close
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Add Case Modal */}
      {isAddModalOpen && (
        <div style={{ position: 'fixed', inset: 0, background: 'rgba(0,0,0,0.5)', display: 'flex', alignItems: 'center', justifyContent: 'center', zIndex: 1000, padding: '1rem' }}>
          <div style={{ background: 'white', borderRadius: '8px', padding: '1.5rem', width: '100%', maxWidth: '480px' }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '1.25rem' }}>
              <h3 style={{ margin: 0, fontSize: '1.1rem' }}>Schedule Digital X-Ray</h3>
              <button onClick={() => setIsAddModalOpen(false)} style={{ border: 'none', background: 'none', cursor: 'pointer', color: '#64748b' }}>
                <XMarkIcon style={{ width: '20px' }} />
              </button>
            </div>

            <form onSubmit={handleAddCase}>
              <div className="setup-form-group">
                <label className="setup-label">Patient Name</label>
                <input
                  type="text"
                  className="setup-input"
                  placeholder="e.g. Gurpreet Singh"
                  value={newCase.patient}
                  onChange={(e) => setNewCase({ ...newCase, patient: e.target.value })}
                  required
                />
              </div>

              <div style={{ display: 'flex', gap: '1rem', marginBottom: '1rem' }}>
                <div style={{ flex: 1 }}>
                  <label className="setup-label">Age / Gender</label>
                  <input
                    type="text"
                    className="setup-input"
                    placeholder="e.g. 50/M"
                    value={newCase.age}
                    onChange={(e) => setNewCase({ ...newCase, age: e.target.value })}
                    required
                  />
                </div>
                <div style={{ flex: 1 }}>
                  <label className="setup-label">Radiologist</label>
                  <select
                    className="setup-input"
                    value={newCase.radiologist}
                    onChange={(e) => setNewCase({ ...newCase, radiologist: e.target.value })}
                  >
                    <option value="Dr. John Smith">Dr. John Smith</option>
                    <option value="Dr. Emily Davis">Dr. Emily Davis</option>
                  </select>
                </div>
              </div>

              <div className="setup-form-group">
                <label className="setup-label">Investigation / Exposure Region</label>
                <select
                  className="setup-input"
                  value={newCase.investigations}
                  onChange={(e) => setNewCase({ ...newCase, investigations: e.target.value })}
                >
