returns jsonb
language plpgsql
security definer
set search_path = public, auth, extensions
as $$
declare
  v_user_id uuid;
  v_question text;
  v_cleaned_email text;
begin
  v_cleaned_email := lower(trim(p_email));

  if v_cleaned_email is null or v_cleaned_email = '' then
